// Mon Coach — recettes (partie 6/6), portées depuis l'app Firebase/Vercel d'origine.
const RECIPES_PART6 = [
{n:"Émincé de poulet au miel et à la cannelle",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:410,p:46,c:18,f:17,prep:20,ing:["escalope de poulet","oignon","ail haché","cannelle","miel liquide","sauce soja","huile","beurre"],qty:["2","1","1 cuillère à soupe","1 cuillère à café","2 cuillères à café","2,5 cuillères à soupe","1 cuillère à soupe","15 g"],steps:["Couper l'oignon en quartiers d'environ 1 cm de large et séparer les épaisseurs. Détailler les escalopes de poulet en fines lanières.","Dans un wok ou une sauteuse à feu très vif, faire revenir le poulet dans le beurre jusqu'à ce qu'il soit à peine coloré sur toutes les faces.","Ajouter l'huile et l'oignon, saler, poivrer et remuer quelques instants, puis ajouter l'ail haché et la cannelle.","Arroser avec 2 cuillères à soupe de sauce soja, mélanger, verser un peu d'eau et ajouter une cuillère à café de miel. Faire réduire à gros bouillons.","Quand il ne reste presque plus de liquide, ajouter le reste de sauce soja et de miel, retirer du feu et rectifier l'assaisonnement. Servir avec du riz, des nouilles sautées ou des brocolis à peine croquants."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
{n:"Tagliatelles à la crème de poireaux et aux lardons",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:840,p:26,c:88,f:42,prep:30,ing:["tagliatelles","poireau","lardons","crème fraîche","parmesan","beurre"],qty:["250 g","1","75 g","10 cl","30 g","20 g"],steps:["Laver et couper le poireau en fines rondelles, puis le faire fondre environ 15 minutes dans une poêle avec un morceau de beurre, en remuant souvent.","Faire cuire les tagliatelles selon les indications du paquet.","Quand le poireau est bien fondu, ajouter les lardons et laisser dorer.","Hors du feu, incorporer la crème fraîche, saler et poivrer à votre goût.","Égoutter les tagliatelles, les disposer dans un plat et napper de la sauce aux poireaux et lardons.","Parsemer de parmesan râpé et servir aussitôt."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
{n:"Poulet au curry, lait de coco et noix de cajou",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:660,p:41,c:15,f:48,prep:25,ing:["filet de poulet","lait de coco","noix de cajou","sauce soja","curry","maïzena","huile"],qty:["2","20 cl","40 g","1 cuillère à soupe","1 cuillère à café","1 cuillère à soupe","2 cuillères à soupe"],steps:["Concasser grossièrement les noix de cajou grillées et salées pour obtenir un mélange de poudre et de petits morceaux.","Couper les filets de poulet en cubes d'environ 1 à 2 cm ou en fines lanières, puis les enrober de maïzena.","Faire chauffer le curry dans l'huile chaude jusqu'à ce que ses parfums se dégagent.","Ajouter le poulet et laisser dorer 5 minutes.","Verser la sauce soja puis le lait de coco, mélanger et laisser cuire 10 minutes. Ajouter les noix de cajou 5 minutes avant la fin de la cuisson. Saler et poivrer."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:true,sans_gluten:false,sans_fruits_a_coque:false}},
{n:"Blanquette de crevettes à la tomate et au citron vert",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:450,p:49,c:13,f:22,prep:45,ing:["crevettes roses cuites","carotte","tomate","oignon","crème fraîche","maïzena","vin blanc sec","citron vert","beurre"],qty:["400 g","1","2","1","10 cl","1/2 cuillère à soupe","5 cl","1/2","10 g"],steps:["Décortiquer les crevettes et faire revenir les têtes et les carapaces dans le beurre, puis arroser de vin blanc. Dès l'ébullition, ajouter 40 cl d'eau, un bouquet garni et l'oignon émincé, et laisser frémir à découvert pendant 20 minutes.","Pendant ce temps, éplucher la carotte et la couper en bâtonnets. Ébouillanter les tomates, les peler, les épépiner et couper la chair en quartiers.","Filtrer le fumet de crevettes et le reporter à ébullition. Ajouter la carotte et la tomate et laisser cuire 15 minutes. Saler et poivrer.","Mélanger la crème fraîche et la maïzena, incorporer dans le fumet et laisser épaissir quelques minutes.","Ajouter les crevettes décortiquées et le jus de citron vert, laisser chauffer quelques instants et servir chaud."],diet:{vegetarien:false,vegan:false,sans_poisson:false,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Pavé de saumon sur lit de poireaux à la crème",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:520,p:32,c:6,f:40,prep:40,ing:["saumon","poireau","crème fraîche épaisse","huile"],qty:["2 pavés","2","10 cl","1 cuillère à soupe"],steps:["Laver les poireaux et les couper en rondelles (le blanc et environ 3 cm de vert).","Faire fondre les poireaux dans une poêle avec l'huile, à couvert, pendant environ 15 minutes pour qu'ils ne grillent pas. En fin de cuisson, ajouter sel, poivre et curry selon le goût.","Disposer les poireaux dans un plat allant au four, recouvrir des pavés de saumon (poivrer si désiré) puis napper le tout de crème fraîche épaisse.","Fermer hermétiquement le plat avec du papier aluminium et cuire au four à 180-190°C (thermostat 6-7) pendant environ 20 minutes selon la grosseur du saumon."],diet:{vegetarien:false,vegan:false,sans_poisson:false,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Feuilleté au jambon et au chèvre",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:680,p:25,c:45,f:45,prep:35,ing:["pâte feuilletée","jambon blanc","champignons de Paris (boîte)","bûche de chèvre","oeuf"],qty:["1 rouleau (230 g)","2 tranches","1 petite boîte (115 g)","100 g","1"],steps:["Dérouler la pâte feuilletée dans un plat allant au four. Sur une moitié, répartir le jambon haché, puis les champignons égouttés, le chèvre en rondelles et enfin l'oeuf battu.","Replier l'autre moitié de la pâte par-dessus pour former un grand chausson et bien souder les bords.","Faire cuire à four assez chaud (thermostat 7 / 210°C) pendant une vingtaine de minutes."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
{n:"Cuisses de canard braisées au miel, gingembre et raisins secs",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:650,p:35,c:30,f:43,prep:100,ing:["cuisse de canard","oignon","raisins secs blonds","crème fraîche","miel","vinaigre balsamique","ail","gingembre en poudre","cumin","coriandre en poudre","bouillon de volaille"],qty:["2 cuisses","1","30 g","8 cl","1 cuillère à soupe","1 cuillère à soupe","1 gousse","1/2 cuillère à soupe","1/2 cuillère à soupe","1/2 cuillère à soupe","1/2 cube (dans 50 cl d'eau)"],steps:["Émincer l'oignon et hacher l'ail, puis diluer le demi-cube de bouillon de volaille dans 50 cl d'eau bouillante.","Saler et poivrer les cuisses de canard des deux côtés puis les faire colorer dans une sauteuse, côté peau en premier, dans leur propre graisse. Réserver.","Retirer l'excès de graisse rendue si nécessaire, puis faire blondir l'oignon avec le miel et le vinaigre balsamique dans la sauteuse.","Ajouter le bouillon, l'ail, les raisins secs, le gingembre, le cumin et la coriandre, puis bien mélanger.","Remettre les cuisses de canard dans la sauteuse, couvrir et laisser mijoter à feu doux pendant 1 heure.","Découvrir et laisser réduire le jus à feu moyen-vif pendant 15 minutes. Réserver les cuisses, puis ajouter la crème fraîche dans la sauce et porter à ébullition.","Rectifier l'assaisonnement et servir les cuisses de canard nappées de sauce."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Boeuf bourguignon mijoté deux jours aux carottes",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:550,p:35,c:15,f:38,prep:300,ing:["bourguignon (viande de boeuf)","carotte","oignon","vin rouge","beurre"],qty:["300 g","2","2","1/2 bouteille","50 g"],steps:["Couper la viande en cubes de 3 cm en retirant les gros morceaux de gras.","Couper les oignons en morceaux et les faire revenir au beurre dans une poêle jusqu'à ce qu'ils soient transparents, puis les transférer dans une cocotte en fonte.","Faire dorer la viande dans la même poêle, en plusieurs fournées, en rajoutant du beurre si besoin, et l'ajouter au fur et à mesure dans la cocotte.","Déglacer la poêle avec un peu d'eau ou de vin en raclant les sucs, saler, poivrer et verser dans la cocotte.","Recouvrir la viande avec une partie du vin rouge, ajouter les carottes coupées en rondelles et un bouquet garni, puis laisser mijoter plusieurs heures.","Le lendemain, poursuivre la cuisson à feu doux au moins 2 heures, en ajoutant du vin ou de l'eau si nécessaire, jusqu'à ce que la viande soit fondante."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Papillotes de saumon au miel, curry et gingembre",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:430,p:32,c:18,f:26,prep:35,ing:["pavé de saumon","oignon","crème fraîche","miel","curry en poudre","gingembre en poudre","beurre"],qty:["2 pavés (150 g chacun)","75 g","2 cuillères à soupe","2 cuillères à soupe","1 cuillère à café","1 cuillère à café","8 g"],steps:["Émincer les oignons et les faire revenir dans un filet d'huile jusqu'à ce qu'ils caramélisent légèrement.","Découper deux grands rectangles de papier aluminium pour former deux papillotes et déposer un pavé de saumon dans chacune.","Répartir sur chaque pavé une demi-cuillère à café de curry, de gingembre, la moitié des oignons, une cuillère à soupe de crème fraîche, une cuillère à soupe de miel et un petit morceau de beurre. Saler légèrement et poivrer.","Fermer hermétiquement les papillotes et enfourner à 210°C (thermostat 7) pendant environ 20 minutes."],diet:{vegetarien:false,vegan:false,sans_poisson:false,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Blanquette de poisson aux champignons de Paris",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:350,p:28,c:10,f:22,prep:30,ing:["lieu noir ou cabillaud","champignons de Paris","oignon","vin blanc","crème fraîche liquide","farine","beurre"],qty:["300 g","200 g (en boîte, égouttés)","1/2","8 cl","8 cl","2 cuillères à soupe","20 g"],steps:["Émincer l'oignon et le faire dorer avec un peu de beurre dans une cocotte.","Ajouter les champignons égouttés puis le vin blanc et porter à ébullition.","Verser la crème fraîche, ajouter un bouquet garni, saler et poivrer, puis laisser réduire légèrement.","Rincer et éponger les filets de poisson, puis les fariner en retirant l'excédent.","Déposer les filets dans la cocotte, baisser le feu et laisser cuire 20 minutes."],diet:{vegetarien:false,vegan:false,sans_poisson:false,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
{n:"Risotto aux poireaux et parmesan",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:520,p:14,c:65,f:22,prep:30,ing:["poireau","riz pour risotto","vin blanc sec","crème fraîche","parmesan râpé","beurre","bouillon de légumes"],qty:["1 belle pièce et demie","2 louches (environ 150 g)","10 cl","3 cuillères à soupe","40 g","25 g","1/2 cube (dans 75 cl d'eau)"],steps:["Émincer le blanc du poireau et diluer le demi-cube de bouillon dans 75 cl d'eau bouillante.","Faire fondre le beurre dans une sauteuse et faire étuver le poireau 5 minutes sans le laisser brunir.","Ajouter le riz et remuer à feu vif jusqu'à ce qu'il devienne translucide.","Verser le vin blanc et laisser s'évaporer, puis ajouter le bouillon louche par louche, à feu doux, en remuant jusqu'à absorption complète, environ 20 minutes.","Hors du feu, incorporer la crème fraîche, du poivre et le parmesan râpé. Laisser reposer 3 minutes à couvert avant de servir bien chaud."],diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Tajine d'agneau aux pommes de terre, olives et safran",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:560,p:32,c:40,f:30,prep:70,ing:["selle d'agneau ou agneau désossé","pomme de terre","carotte","courgette","tomate","oignon","olives vertes","huile d'olive","épices (cumin, muscade, gingembre, coriandre, cannelle)","safran"],qty:["300 g","5 moyennes","1","1","1","1","une poignée","3 cuillères à soupe","1 cuillère à café","1 pincée"],steps:["Verser l'huile d'olive dans le plat à tajine posé sur le feu et faire revenir la viande de chaque côté pendant environ 10 minutes.","Baisser le feu et disposer les légumes lavés et coupés grossièrement en pyramide sur la viande, des plus fermes aux plus tendres : pommes de terre, carotte, courgette puis oignon, en intercalant le cumin, les épices, le sel et le poivre entre les couches.","Arroser d'un peu d'eau, saupoudrer de safran et déposer les olives vertes.","Couvrir et laisser cuire à feu doux pendant 30 minutes.","Ajouter les tomates coupées en morceaux sur les légumes, couvrir et prolonger la cuisson 15 minutes.","Servir chaud, directement dans le plat à tajine, avec du pain."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Lasagnes végétariennes aux courgettes et à la tomate",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:480,p:20,c:45,f:24,prep:75,ing:["pâtes à lasagnes","gruyère râpé","oignon","tomate fraîche","courgette","coulis de tomate","béchamel","basilic frais"],qty:["9 feuilles environ","200 g","2","3","2","100 g","25 cl","quelques feuilles"],steps:["Faire revenir les oignons émincés dans une sauteuse jusqu'à ce qu'ils soient fondants.","Ajouter les tomates coupées en morceaux et laisser mijoter avec un peu d'herbes de Provence, sel et poivre.","Incorporer les courgettes coupées en rondelles, le coulis de tomate et une cuillère à café de sucre, puis laisser mijoter l'ensemble environ 20 minutes à feu moyen.","Dans un grand plat, monter les lasagnes en couches successives : pâtes, préparation aux légumes, béchamel, gruyère râpé, et recommencer, en terminant par une couche généreuse de gruyère.","Enfourner à four chaud, 200°C (thermostat 7), pendant 35 minutes.","Parsemer de basilic frais et servir bien gratiné."],diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
{n:"Paupiettes de veau aux tomates, champignons et olives noires",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:420,p:35,c:12,f:26,prep:45,ing:["paupiette de veau","oignon jaune","tomate","champignons de Paris","ail","vin blanc","olives noires","huile d'olive","basilic"],qty:["2","1","2","1 petite boîte (200 g)","1 gousse","5 cuillères à soupe","une poignée","2 cuillères à soupe","quelques feuilles"],steps:["Émincer l'oignon et hacher l'ail.","Faire dorer les paupiettes dans une sauteuse avec l'huile d'olive, saler et poivrer, puis les réserver.","Faire suer l'oignon et l'ail dans la même sauteuse, en ajoutant un peu d'huile si nécessaire.","Une fois bien colorés, ajouter les tomates et les champignons, assaisonner avec sel, poivre, herbes de Provence et basilic, puis laisser cuire 2 minutes.","Remettre les paupiettes dans la sauteuse, arroser de vin blanc et ajouter les olives noires.","Laisser mijoter à feu doux pendant 20 à 30 minutes et servir avec des haricots verts ou du riz."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Gratin de courge butternut à la poitrine fumée et au parmesan",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:380,p:16,c:25,f:24,prep:35,ing:["courge butternut","poitrine fumée","crème liquide","parmesan râpé","pignons de pin","herbes fraîches (cerfeuil, persil, ciboulette)","muscade"],qty:["600 g (1/2 courge)","100 g","5 cl","30 g","1 cuillère à soupe","1 cuillère à soupe","1 pincée"],steps:["Couper la courge butternut en cubes de 3 cm, l'éplucher, puis la cuire 5 minutes à la vapeur ou dans un fond d'eau non salée jusqu'à ce qu'elle soit tendre sans s'effondrer.","Pendant ce temps, hacher grossièrement la poitrine fumée.","Disposer la courge et la poitrine dans un plat à gratin en mélangeant délicatement, puis parsemer d'herbes hachées et de pignons de pin.","Assaisonner de muscade et de poivre, saler très légèrement car la poitrine est déjà salée, verser la crème liquide et saupoudrer de parmesan râpé.","Enfourner 20 minutes dans un four préchauffé à 210°C et servir bien chaud, accompagné d'une salade verte."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Courgettes farcies à la viande hachée et au fromage",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:420,p:28,c:14,f:28,prep:50,ing:["courgette","viande hachée (porc ou boeuf)","oignon","fromage râpé","coulis de tomate","huile d'olive"],qty:["2","300 g","1/2","50 g","10 cl","2 cuillères à soupe"],steps:["Laver les courgettes sans les peler, les couper en deux dans le sens de la longueur pour obtenir 4 barquettes, puis évider chacune à la petite cuillère en réservant la chair.","Faire revenir la chair de courgette avec l'oignon émincé dans la moitié de l'huile d'olive, puis ajouter la viande hachée et l'émietter à la fourchette en la faisant bien revenir.","Assaisonner de sel et de poivre, disposer les barquettes de courgettes côte à côte dans un plat allant au four, les garnir de la farce et arroser de coulis de tomate.","Enfourner à 200°C pendant 30 à 40 minutes.","Quelques minutes avant la fin de la cuisson, parsemer de fromage râpé et poursuivre la cuisson jusqu'à ce qu'il fonde, puis passer sous le grill quelques instants pour bien dorer."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Risotto au poulet et chorizo",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:660,p:35,c:62,f:30,prep:40,ing:["riz arborio","oignon","vin blanc","bouillon de volaille","parmesan","beurre","poivrons rouge, vert et jaune","blanc de poulet","chorizo","petits pois"],qty:["180 g","1","10 cl","40 cl","30 g","20 g","1 de chaque (petits)","300 g","100 g","100 g"],steps:["Émincer l'oignon et le faire revenir dans un mélange de beurre et d'huile d'olive.","Ajouter le riz et remuer jusqu'à ce qu'il devienne translucide, puis verser le vin blanc et laisser évaporer.","Verser le bouillon de volaille chaud louche par louche, en remuant régulièrement, jusqu'à absorption complète et cuisson du riz, soit environ 18 minutes.","Saler, poivrer, retirer du feu et incorporer une noix de beurre et le parmesan. Réserver au chaud.","Dans une poêle, faire revenir des lamelles d'oignon dans l'huile d'olive, puis ajouter le poulet en dés, le chorizo en tranches, les poivrons coupés en petits dés et les petits pois. Laisser cuire 10 minutes jusqu'à ce que le tout soit bien doré.","Ajouter cette garniture au risotto, mélanger et servir aussitôt."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Cassoulet au confit de canard et saucisses de Toulouse",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:850,p:42,c:58,f:50,prep:240,ing:["haricots blancs (mogettes)","saucisson à l'ail","saucisses de Toulouse","poitrine de porc fraîche","poitrine de porc fumée","confit de canard","concentré de tomates"],qty:["250 g","4 tranches","2","1 tranche","1 tranche","2 cuisses","1 cuillère à soupe"],steps:["La veille, faire tremper les haricots blancs dans l'eau froide toute la nuit.","Égoutter les haricots et les cuire à la cocotte dans l'eau froide non salée avec quelques gousses d'ail, du thym et du laurier, environ 30 à 45 minutes à partir de l'ébullition.","Égoutter à nouveau les haricots et les remettre dans une grande cocotte couverte d'eau. Ajouter le concentré de tomates, le saucisson en rondelles, la poitrine fumée coupée en morceaux, de l'ail, du thym et du laurier, puis laisser mijoter.","Dans une poêle, faire griller la poitrine fraîche coupée en morceaux puis les saucisses ; éponger l'excès de graisse et les ajouter dans la cocotte. Saler, poivrer et laisser mijoter 1 heure à feu très doux en remuant de temps en temps.","Nettoyer les cuisses de confit de canard de leur graisse, les séparer en hauts et bas de cuisses, puis les ajouter dans la cocotte. Rectifier l'assaisonnement et laisser encore mijoter 30 minutes.","Préchauffer le four à 110°C en chaleur tournante. Frotter deux plats à gratin en terre cuite avec de l'ail, y répartir le contenu de la cocotte en veillant à ce que la sauce arrive juste au niveau des haricots, puis saupoudrer de chapelure.","Enfourner et laisser cuire doucement 1 à 2 heures, en surveillant que la sauce reste au niveau des haricots et en enfonçant régulièrement les morceaux de viande dans le jus. Le cassoulet est encore meilleur réchauffé le lendemain."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:true,sans_gluten:false,sans_fruits_a_coque:true}},
{n:"Tartiflette au reblochon et vin blanc de Savoie",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:780,p:32,c:55,f:48,prep:55,ing:["pomme de terre","oignon","lardons fumés","reblochon","vin blanc de Savoie","crème fraîche liquide"],qty:["700 g","2","125 g","½ (environ 250 g)","5 cl","10 cl"],steps:["Cuire les pommes de terre à l'eau pendant 20 minutes, puis les éplucher et les couper en rondelles.","Émincer les oignons et les faire revenir dans un peu de beurre, puis ajouter les lardons fumés et laisser dorer une dizaine de minutes à feu doux en remuant régulièrement.","Préchauffer le four à 190°C. Frotter le fond d'un plat à gratin avec une gousse d'ail.","Disposer la moitié des pommes de terre dans le plat, ajouter le mélange oignons-lardons, puis recouvrir du reste des pommes de terre.","Verser le vin blanc et la crème fraîche liquide par-dessus. Saler légèrement et poivrer généreusement.","Gratter le reblochon, le couper en deux dans l'épaisseur et le poser côté croûte vers le haut sur les pommes de terre.","Enfourner environ 20 minutes en position gril, jusqu'à ce que le fromage soit bien doré. Servir aussitôt, éventuellement parsemé de persil haché."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Blanquette de veau à l'ancienne au jaune d'oeuf et citron",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:540,p:38,c:13,f:37,prep:190,ing:["veau à blanquette","os de veau","carotte","oignon","beurre","farine","crème fraîche","jaune d'oeuf","citron"],qty:["500 g","1","2","1","20 g","1 cuillère à soupe","20 cl","1","1"],steps:["Dans une cocotte, mettre la viande de veau, l'os, un bouquet garni (thym, laurier, persil, quelques grains de poivre), les carottes en rondelles et l'oignon. Couvrir d'eau froide, saler au gros sel, porter à ébullition et écumer.","Laisser mijoter environ 2h30 à couvert, ou 1 heure en cocotte-minute.","Préparer un roux blond en fouettant le beurre et la farine à feu doux pendant 5 minutes dans une casserole, puis réserver hors du feu.","Prélever le bouillon chaud de la blanquette, le filtrer en retirant l'oignon et le bouquet garni, et réserver la viande et les carottes dans un plat.","Hors du feu, incorporer peu à peu le bouillon filtré au roux en fouettant vigoureusement pour éviter les grumeaux.","Remettre sur feu vif et porter à ébullition 5 minutes en fouettant sans cesse, jusqu'à ce que la sauce nappe la cuillère. Ajouter le jus de citron et laisser cuire encore 2 minutes.","Pendant ce temps, battre la crème fraîche avec le jaune d'oeuf, du sel et du poivre, puis incorporer ce mélange à la sauce veloutée.","Remettre la viande et les carottes dans la sauce, mélanger délicatement pour bien les enrober et servir aussitôt avec du riz blanc."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
{n:"Gigot d'agneau confit sept heures au cognac",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:720,p:48,c:8,f:54,prep:420,ing:["gigot d'agneau","huile d'olive","oignon","carotte","couenne de porc","tomates pelées","vin blanc","bouillon de boeuf","cognac"],qty:["600 g","1 cuillère à soupe","1","1","50 g","100 g","10 cl","10 cl","2 cl"],steps:["Saler et poivrer le gigot d'agneau, puis le faire dorer de toutes parts dans l'huile d'olive chaude.","Tapisser le fond d'une cocotte de couenne, côté gras vers l'extérieur. Y déposer le gigot, entourer des carottes, de l'oignon et des tomates pelées.","Ajouter le vin blanc, le bouillon de boeuf, le cognac et un bouquet garni (thym, laurier, persil, clou de girofle). Saler et poivrer.","Couvrir et cuire au four à 120-140°C pendant environ 5 à 7 heures, en surveillant régulièrement et en rajoutant un peu d'eau si nécessaire, jusqu'à ce que la viande soit fondante au point de se couper à la cuillère.","Rectifier l'assaisonnement et servir directement à la cuillère dans la cocotte."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Tarte à la courgette, lardons et curry",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:560,p:20,c:35,f:36,prep:45,ing:["pâte brisée","courgette","lardons","oignon","oeuf","crème liquide","curry"],qty:["1","1 grosse","100 g","1","2","10 cl","1 cuillère à café"],steps:["Préchauffer le four à 220°C. Étaler la pâte brisée dans un moule à tarte.","Faire rissoler les lardons et l'oignon émincé dans une poêle, puis ajouter les rondelles de courgette et laisser cuire quelques minutes.","Battre les oeufs avec la crème liquide, saler, poivrer et ajouter le curry.","Répartir la garniture de lardons, courgette et oignon sur le fond de tarte, puis verser l'appareil aux oeufs et à la crème.","Cuire 30 minutes au four, jusqu'à ce que le dessus soit bien doré."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
{n:"Cailles à la moutarde et au miel",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:520,p:32,c:18,f:34,prep:65,ing:["cailles","beurre","miel","moutarde de Dijon"],qty:["4","25 g","2 cuillères à soupe","1 cuillère à soupe"],steps:["Faire fondre à feu doux le beurre et le miel, puis hors du feu ajouter la moutarde, du sel et du poivre.","Badigeonner les cailles de ce mélange dans un plat allant au four, couvrir de papier aluminium et laisser mariner 2 heures à température ambiante ou toute une nuit au réfrigérateur.","Préchauffer le four à 210°C.","Enfourner le plat couvert d'aluminium pendant 25 minutes, puis retirer le papier et poursuivre la cuisson 25 à 30 minutes en arrosant régulièrement avec la sauce.","Servir les cailles bien dorées, accompagnées par exemple de tagliatelles au citron."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Lasagnes aux courgettes et au chèvre",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:540,p:24,c:45,f:28,prep:40,ing:["plaques de lasagnes","courgette","fromage de chèvre frais","lait","maïzena","gruyère râpé"],qty:["5","2","150 g","25 cl","1 cuillère à soupe","30 g"],steps:["Préchauffer le four à 180°C. Laver et râper les courgettes, puis les faire revenir 15 minutes à feu doux dans une poêle.","Ajouter le fromage de chèvre frais aux courgettes, saler et poivrer.","Faire cuire les plaques de lasagnes selon les indications. Préparer une béchamel légère en portant le lait à ébullition puis en ajoutant la Maïzena délayée, en remuant à feu doux jusqu'à épaississement ; saler, poivrer et ajouter une pincée de muscade.","Dans un plat à gratin, alterner la béchamel, les plaques de lasagnes et le mélange courgettes-chèvre, en terminant par la béchamel. Parsemer de gruyère râpé.","Enfourner 20 à 25 minutes."],diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
{n:"Rôti de veau en cocotte aux champignons de Paris",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:450,p:40,c:8,f:27,prep:40,ing:["rôti de veau","champignons de Paris","oignon","vin blanc","fond de veau","beurre"],qty:["500 g","200 g","1","20 cl","2 cuillères à café","15 g"],steps:["Faire fondre le beurre dans une cocotte-minute et y faire dorer le rôti de veau sur toutes ses faces. Ajouter l'oignon émincé, saler et poivrer.","Délayer le fond de veau avec le vin blanc, un verre d'eau, une pincée d'herbes de Provence et de basilic. Verser ce mélange dans la cocotte avec les champignons de Paris lavés et coupés en quartiers, puis remuer.","Fermer la cocotte et laisser cuire environ 30 minutes par kilo de viande, soit environ 20 minutes pour ce rôti."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Osso bucco milanais au gremolata de citron",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:510,p:40,c:14,f:32,prep:115,ing:["jarret de veau (osso bucco)","oignon","carotte","céleri","pulpe de tomate","ail","vin blanc","bouillon de volaille","farine","citron","persil"],qty:["2 tranches","1","1","1 branche","150 g","1 gousse","10 cl","1 cube","1 cuillère à soupe","1","1/2 bouquet"],steps:["Hacher finement l'oignon et la carotte, puis les faire revenir 10 minutes dans une cocotte avec un peu d'huile d'olive.","Ajouter l'ail écrasé, la pulpe de tomate, le céleri ficelé avec une feuille de laurier, et les queues de persil.","Fariner légèrement les tranches d'osso bucco et les faire dorer des deux côtés à la poêle dans de l'huile d'olive. Saler et poivrer.","Déposer les tranches de viande dans la sauce tomate. Déglacer la poêle avec le vin blanc et verser dans la cocotte.","Ajouter le bouillon de volaille émietté et 15 à 20 cl d'eau. Couvrir et laisser mijoter 1h30.","Râper le zeste du citron, le mélanger au persil haché pour préparer la gremolata, puis la verser dans la cocotte en fin de cuisson. Laisser cuire encore 5 minutes avant de servir."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:true,sans_gluten:false,sans_fruits_a_coque:true}},
{n:"Saumon à l'échalote et à la crème balsamique",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:420,p:32,c:6,f:30,prep:20,ing:["saumon","échalotes","beurre","crème fraîche","moutarde","vinaigre balsamique"],qty:["2 pavés (environ 300 g)","3","1 noisette","1 cuillère à soupe","1 cuillère à café","2 cuillères à soupe"],steps:["Faire revenir les échalotes émincées dans le beurre jusqu'à ce qu'elles deviennent translucides, puis ajouter les pavés de saumon et saler légèrement.","Une fois le saumon cuit, le réserver dans une assiette. Déglacer les échalotes avec le vinaigre balsamique allongé d'un peu d'eau.","Ajouter la moutarde et laisser mijoter 2 à 3 minutes, puis incorporer la crème fraîche.","Remettre les pavés de saumon dans la poêle juste avant de servir pour les réchauffer.","Servir bien chaud avec du riz ou du chou romanesco."],diet:{vegetarien:false,vegan:false,sans_poisson:false,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Pot-au-feu à l'autocuiseur",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:500,p:35,c:35,f:24,prep:55,ing:["viande à pot-au-feu","poireau","carottes","pommes de terre","oignon","navet","chou","ail"],qty:["400 g","1","2","300 g","1","1","¼","1 tête"],steps:["Dégraisser légèrement la viande, la couvrir d'eau froide et ajouter un bouquet garni, l'oignon épluché, la tête d'ail et du gros sel.","Cuire en pression pendant 30 minutes.","Pendant ce temps, éplucher les légumes (poireau, carottes, navet, chou).","Relâcher la pression, ajouter les légumes épluchés (hors pommes de terre) et cuire de nouveau en pression 5 minutes.","Relâcher la pression, ajouter les pommes de terre et cuire encore 10 minutes en pression. Servir chaud."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Risotto aux asperges fraîches",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:450,p:13,c:56,f:19,prep:35,ing:["asperges vertes","riz pour risotto","échalotes","beurre","vin blanc","bouillon de légumes","parmesan"],qty:["1 botte","150 g","2","25 g + 1 noix","8 cl","50 cl","50 g"],steps:["Préparer les asperges en cassant la base dure d'un coup sec et en les pelant si nécessaire ; les couper en tronçons en réservant les pointes.","Faire fondre le beurre dans une poêle et y faire suer les échalotes finement émincées.","Ajouter les asperges (sans les pointes) et laisser cuire doucement 5 minutes.","Ajouter le riz, augmenter le feu puis verser le vin blanc.","Verser le bouillon de légumes chaud en trois fois, en attendant à chaque fois qu'il soit absorbé avant d'ajouter la suite.","À mi-cuisson, ajouter les pointes d'asperges ; le riz doit rester crémeux, pas croquant. Saler légèrement et poivrer en fin de cuisson.","Hors du feu, incorporer le parmesan râpé et la noix de beurre, bien mélanger et servir aussitôt bien chaud."],diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Risotto crémeux aux champignons et mascarpone",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:650,p:22,c:44,f:43,prep:60,ing:["champignons","riz rond","crème fraîche","parmesan","mascarpone","oignon","ail"],qty:["250 g","100 g","15 cl","75 g","2 cuillères à soupe","1","1 gousse"],steps:["Faire blanchir les champignons 5 minutes dans un demi-litre d'eau salée, les égoutter en conservant le bouillon.","Dans une casserole à fond épais, faire revenir l'oignon, l'ail et le persil hachés finement dans deux cuillères à soupe de crème fraîche.","Ajouter le riz, les champignons, le reste de la crème et le mascarpone, puis recouvrir avec le bouillon de cuisson des champignons. Assaisonner.","Laisser cuire à couvert à feu moyen jusqu'à ce que le riz soit fondant et la sauce crémeuse, au moins 45 minutes.","Hors du feu, incorporer le parmesan râpé et bien remuer. Servir bien chaud, éventuellement accompagné de langoustines."],diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Sauté de porc à la crème de moutarde à l'ancienne",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:560,p:34,c:12,f:42,prep:45,ing:["sauté de porc","carottes","oignon","vin blanc","crème fraîche épaisse","moutarde à l'ancienne","beurre","huile d'olive","farine"],qty:["500 g","2","1","13 cl","10 cl","1 cuillère à soupe","15 g","1 cuillère à soupe","1 cuillère à soupe"],steps:["Faire revenir les morceaux de sauté de porc dans l'huile d'olive.","Éplucher et couper les carottes en rondelles, émincer l'oignon, puis les faire revenir dans une cocotte avec le beurre.","Une fois dorés, ajouter 13 cl d'eau et le vin blanc, puis le sauté de porc. Fermer la cocotte et laisser cuire 25 minutes à partir du chuchotement de la vapeur.","Retirer la viande de la cocotte, puis incorporer la moutarde et la crème épaisse dans le jus de cuisson en mélangeant bien.","Ajouter la farine petit à petit en remuant pour épaissir la sauce.","Remettre le sauté de porc dans la sauce et laisser mijoter 5 minutes à couvert pour qu'il s'imprègne.","Servir avec des pommes de terre sautées ou des pâtes fraîches."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
{n:"Gratin de courgettes à la viande hachée",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:520,p:28,c:10,f:40,prep:45,ing:["courgettes","viande hachée","coulis de tomate","crème fraîche liquide","gruyère râpé","oignon"],qty:["2","250 g","20 cl","15 cl","100 g","1"],steps:["Couper la moitié de l'oignon en lamelles et les courgettes en rondelles.","Dans un filet d'huile d'olive, faire revenir la moitié de l'oignon avec les courgettes ; saler, poivrer et laisser cuire jusqu'à ce qu'elles soient tendres tout en restant un peu fermes.","Dans un autre filet d'huile d'olive, faire revenir le reste de l'oignon sans le griller, puis ajouter la viande hachée ; saler, poivrer.","Une fois la viande cuite, ajouter la crème fraîche et le coulis de tomate. Rectifier l'assaisonnement et laisser mijoter jusqu'à léger épaississement.","Égoutter les courgettes à l'aide d'une écumoire et les disposer dans un plat à four.","Verser la préparation à la viande sur les courgettes, parsemer de gruyère râpé et enfourner à thermostat 7 (210°C) jusqu'à ce que le gratin soit doré."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Aubergines farcies à la chair à saucisse et au gruyère",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:320,p:16,c:10,f:24,prep:55,ing:["aubergine","chair à saucisse","oignons","tomate","oeuf","gruyère râpé"],qty:["1","100 g","2","1","1","25 g"],steps:["Couper l'aubergine en deux dans le sens de la longueur et inciser la chair en croisillons avec un couteau pour qu'elle cuise bien à l'intérieur.","Arroser d'un filet d'huile d'olive et enfourner à 250°C pendant 30 minutes.","Retirer la chair des aubergines à la cuillère et la couper finement, en réservant les peaux.","Faire blanchir les oignons émincés à feu doux pendant 15 minutes sans les laisser griller ; au bout de 5 minutes, ajouter la chair à saucisse.","Ajouter la tomate coupée en petits dés et une gousse d'ail, laisser cuire à feu très doux.","Ajouter la chair d'aubergine, saler, poivrer, puis ajouter du persil et du basilic ciselés.","Incorporer l'oeuf battu et bien mélanger.","Garnir les peaux d'aubergine de cette préparation, recouvrir de gruyère râpé et repasser au four chaud 5 à 10 minutes. Servir chaud ou froid."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Lasagnes au bœuf et à la chair à saucisse",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:780,p:42,c:68,f:38,prep:90,ing:["pâtes à lasagnes","boeuf haché","saucisses","tomates en dés","purée de tomate","oignon","carotte","céleri","mozzarella","lait","beurre","maïzena"],qty:["6 feuilles","125 g","75 g","1 boîte (400 g)","25 cl","1","1","1 branche","125 g","25 cl","20 g","20 g"],steps:["Laver et hacher finement l'oignon, la carotte et la branche de céleri, en réservant les feuilles de céleri.","Dans une cocotte, faire chauffer un fond d'huile d'olive, ajouter la moitié du hachis de légumes puis les tomates en dés et la purée de tomate. Ajouter un bouquet de feuilles de céleri et de basilic, à retirer en fin de cuisson.","Laisser mijoter la sauce tomate environ 1 heure à feu doux, en ajoutant un peu d'eau si nécessaire.","Préparer une béchamel classique en faisant fondre le beurre, en ajoutant la maïzena puis le lait petit à petit en remuant jusqu'à épaississement ; réserver.","Dans une autre poêle, faire revenir le reste du hachis de légumes avec un filet d'huile d'olive, ajouter la chair à saucisse et laisser cuire 5 minutes, puis ajouter le boeuf haché.","Une fois la viande bien colorée, la retirer du feu et la mélanger à la béchamel.","Monter les lasagnes en alternant une couche de pâtes, une couche de sauce tomate, une couche de béchamel à la viande, en ajoutant quelques feuilles de basilic entre chaque couche.","Enfourner à four moyen (180°C) pendant 35 minutes, en recouvrant de mozzarella coupée en morceaux quelques minutes avant la fin de cuisson."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
{n:"Cuisse de dinde à la dijonnaise",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:620,p:48,c:32,f:33,prep:90,ing:["cuisse de dinde","pommes de terre","tomate","moutarde de Dijon","crème fraîche","ail","huile d'olive"],qty:["1 (environ 800 g)","400 g","1","1 cuillère à soupe","1 cuillère à soupe","1 gousse","1 cuillère à soupe"],steps:["Préchauffer le four à 240°C (thermostat 8).","Couper les tomates et les épépiner. Éplucher et laver les pommes de terre puis les couper en rondelles de 0,5 cm.","Mélanger la crème fraîche et la moutarde dans un bol avec sel et poivre.","Piquer la cuisse de dinde de petits morceaux d'ail, puis la saler et la poivrer.","Disposer la cuisse de dinde dans un plat allant au four avec les tomates et les pommes de terre. Arroser d'huile d'olive et de 2 cuillères à soupe d'eau.","Enfourner 45 minutes en retournant à mi-cuisson.","Tartiner une face de la cuisse avec le mélange crème-moutarde, laisser cuire 15 minutes, puis retourner, tartiner l'autre face et cuire encore 15 minutes."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Joue de porc braisée à la bière et au miel",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:650,p:42,c:14,f:47,prep:135,ing:["joue de porc","lardons","oignon","bière","miel"],qty:["500 g","125 g","1","25 cl (1 canette)","1 cuillère à soupe"],steps:["Dégraisser la viande.","Faire revenir la joue de porc dans un mélange de beurre et d'huile, puis la réserver avec son jus.","Faire revenir ensemble les lardons et l'oignon émincé dans la même cocotte.","Ajouter le miel, puis remettre la viande. Verser la bière, saler légèrement (les lardons salent déjà) et poivrer.","Couvrir et laisser mijoter 2 heures à feu doux en surveillant régulièrement."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Poulet fermier rôti au citron et au laurier",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:580,p:52,c:6,f:38,prep:115,ing:["poulet fermier","oignon","tomates cerises","ail","citron","bouillon de volaille"],qty:["1 poulet fermier (environ 1,5 kg)","1 oignon","1 poignée de tomates cerises","2 gousses d'ail","1 citron (jus)","1 cube de bouillon de volaille dilué dans un verre d'eau"],steps:["Préchauffer le four à 200 °C (thermostat 6). Glisser l'ail et une feuille de laurier à l'intérieur du poulet.","Mélanger le jus de citron avec le bouillon de volaille dilué. En arroser copieusement le poulet et verser le reste dans le plat.","Saler et poivrer le poulet, puis le déposer dans un plat à four avec l'oignon coupé en quartiers et les tomates cerises.","Enfourner environ 1 h 40. Après 20 minutes de cuisson, retourner le poulet, laisser cuire 20 minutes puis le remettre à l'endroit pour la suite de la cuisson.","Arroser le poulet avec son jus le plus souvent possible pendant la cuisson (ajouter un peu d'eau si nécessaire) pour qu'il reste bien moelleux.","En fin de cuisson, récupérer le jus avec les tomates et l'oignon. Servir le poulet avec une salade verte et des pommes de terre nouvelles sautées."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Gratin de cabillaud aux poivrons et tomates",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:350,p:30,c:15,f:18,prep:45,ing:["cabillaud","oignon","poivrons","tomates","tomates concassées","ail","crème fraîche","fromage râpé"],qty:["2 pavés de cabillaud (environ 300 g)","1 oignon","1 poivron rouge et 1 poivron vert","2 tomates","200 g de tomates concassées (en boîte)","2 gousses d'ail","8 cl de crème fraîche","30 g de fromage râpé"],steps:["Émincer finement l'oignon et les poivrons. Couper les tomates fraîches en petits cubes et hacher l'ail.","Faire revenir le tout à l'huile d'olive à feu moyen, puis ajouter un peu d'herbes de Provence.","Ajouter les tomates concassées et 10 cl d'eau, puis la crème fraîche. Saler, poivrer et laisser mijoter à feu doux jusqu'à ce que les légumes soient fondants.","Préchauffer le four à 180 °C. Déposer le cabillaud dans un plat à gratin.","Napper de sauce, parsemer de basilic et de fromage râpé, puis enfourner 15 à 20 minutes."],diet:{vegetarien:false,vegan:false,sans_poisson:false,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Cake salé aux lardons et à l'emmental",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:430,p:18,c:30,f:26,prep:60,ing:["farine","levure chimique","oeufs","lait","huile","emmental râpé","lardons"],qty:["100 g de farine","1/2 sachet de levure chimique","2 oeufs","5 cl de lait","3 cl d'huile","50 g d'emmental râpé","100 g de lardons poêlés"],steps:["Préchauffer le four à 180 °C (thermostat 6).","Mélanger la farine et la levure dans un saladier.","Ajouter les oeufs, le lait et l'huile, puis mélanger jusqu'à obtenir une pâte lisse.","Incorporer l'emmental râpé, les lardons poêlés, du sel et du poivre.","Verser la préparation dans un moule à cake et enfourner 45 minutes.","Servir chaud avec une salade, ou froid en apéritif."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
{n:"Fondue savoyarde au beaufort, comté et reblochon",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:1150,p:70,c:50,f:74,prep:35,ing:["beaufort","comté","tomme de Savoie","reblochon","vin blanc sec","maïzena","kirsch","ail","pain de campagne"],qty:["150 g de beaufort","150 g de comté","100 g de tomme de Savoie","100 g de reblochon","20 cl de vin blanc sec","1 cuillère à café de maïzena","2 cl de kirsch","1 gousse d'ail","1/2 pain de campagne"],steps:["Couper le pain en cubes à l'avance pour qu'il durcisse légèrement.","Retirer la croûte des fromages et les couper en fines lamelles. Réserver le reblochon à part.","Frotter l'intérieur du caquelon avec la gousse d'ail.","Diluer la maïzena dans le kirsch.","Faire chauffer le vin blanc à feu moyen dans le caquelon. Quand il frémit, baisser le feu et incorporer les fromages en lamelles petit à petit, en remuant en formant des « 8 » avec une cuillère en bois.","Une fois tout le fromage fondu, ajouter le reblochon puis le mélange kirsch-maïzena pour lier la fondue.","Poser le caquelon sur le réchaud et déguster aussitôt en trempant les cubes de pain."],diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
{n:"Brochettes de poulet marinées au curry, miel et moutarde",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:340,p:35,c:10,f:15,prep:30,ing:["blancs de poulet","huile d'olive","moutarde","miel liquide","curry en poudre","cumin"],qty:["2 blancs de poulet (environ 150 g chacun)","5 cl d'huile d'olive","1 cuillère à soupe de moutarde","1 cuillère à soupe de miel liquide","1 cuillère à soupe de curry en poudre","1/2 cuillère à soupe de cumin"],steps:["Couper le poulet en cubes.","Mélanger l'huile, la moutarde, le miel, le curry, le cumin, du sel et du poivre pour préparer la marinade. Y tremper les cubes de poulet puis enfiler 4 brochettes.","Faire cuire les brochettes 10 minutes à la poêle en versant un peu de marinade en cours de cuisson et en les retournant plusieurs fois.","Augmenter légèrement le feu en fin de cuisson pour obtenir un aspect caramélisé.","Servir avec un couscous aux épices ou une salade verte."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Moules à la crème de roquefort et échalotes",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:680,p:42,c:8,f:53,prep:35,ing:["moules","échalotes","vin blanc sec","crème fraîche épaisse","roquefort","beurre demi-sel"],qty:["1,5 kg de moules","3 échalotes","25 cl de vin blanc sec","20 cl de crème fraîche épaisse","125 g de roquefort","20 g de beurre demi-sel"],steps:["Nettoyer soigneusement les moules.","Faire fondre le beurre dans une casserole et y faire suer les échalotes finement hachées.","Ajouter la crème fraîche et le roquefort émietté. Remuer à feu moyen jusqu'à obtenir une sauce lisse, ajouter un peu de persil et assaisonner.","Dans une cocotte, faire chauffer le vin blanc et y verser les moules. Couvrir et laisser ouvrir environ 5 minutes.","Égoutter les moules et les arroser de sauce au roquefort (ou mélanger directement le jus de cuisson filtré à la sauce pour une version plus liquide). Laisser mijoter 5 minutes et servir sans tarder."],diet:{vegetarien:false,vegan:false,sans_poisson:false,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Ragoût de lentilles vertes aux lardons et champignons",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:480,p:25,c:40,f:23,prep:55,ing:["lentilles vertes du Puy","lardons fumés","oignon","carottes","champignons de Paris","coulis de tomate","bouillon de volaille","crème fraîche"],qty:["150 g de lentilles vertes du Puy","75 g de lardons fumés","1 oignon","2 carottes","100 g de champignons de Paris émincés","10 cl de coulis de tomate","25 cl de bouillon de volaille","6 cl de crème fraîche"],steps:["Émincer l'oignon et couper les carottes en rondelles.","Dans une cocotte, faire rissoler l'oignon, puis ajouter les lardons, les carottes, les champignons et une feuille de laurier.","Ajouter le coulis de tomate et les lentilles, puis mouiller avec le bouillon. Saler, poivrer, ajouter des herbes de Provence et laisser cuire environ 25 minutes, jusqu'à ce que les lentilles soient tendres.","Égoutter les lentilles en conservant le jus de cuisson et quelques cuillères de lentilles à part. Ajouter la crème fraîche au jus de cuisson et laisser réduire 15 minutes à feu vif.","Mixer cette sauce puis la mélanger aux lentilles. Servir bien chaud, en plat unique ou en accompagnement."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Souris d'agneau caramélisées au miel et vinaigre balsamique",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:650,p:48,c:20,f:40,prep:210,ing:["souris d'agneau","carottes","échalotes","ail","fond de veau","miel liquide","vinaigre balsamique","vinaigre de xérès","bouillon"],qty:["2 souris d'agneau (environ 400 g chacune)","2 carottes","4 échalotes","8 gousses d'ail en chemise","1 cuillère à soupe de fond de veau","2 cuillères à soupe de miel liquide","2 cuillères à soupe de vinaigre balsamique","2 cuillères à soupe de vinaigre de xérès","50 cl de bouillon"],steps:["Préchauffer le four à 200 °C (thermostat 6/7). Couper les carottes en rondelles et émincer les échalotes.","Faire dorer les souris d'agneau de tous côtés dans une cocotte allant au four, avec un peu d'huile ou de graisse de canard.","Ajouter les carottes, les échalotes, l'ail en chemise, du thym, du romarin et une pincée de cumin.","Mouiller avec le bouillon, ajouter un bouquet garni, saler, poivrer et porter à frémissement.","Enfourner la cocotte à mi-hauteur : compter 30 minutes à 200 °C, puis baisser à 90 °C et poursuivre la cuisson doucement pendant 2 h 30 à 3 h, en arrosant souvent.","Retirer les souris de la cocotte et filtrer le jus de cuisson en pressant bien pour récupérer la pulpe de l'ail confit.","Remettre les souris dans la cocotte, les enduire de miel et les faire caraméliser à feu doux, puis les déglacer avec les deux vinaigres.","Verser le jus filtré dans la cocotte, ajouter le fond de veau et laisser réduire jusqu'à obtenir une sauce nappante. Servir la sauce à part."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Filet mignon de porc au cidre et tomates confites",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:520,p:38,c:12,f:35,prep:65,ing:["filet mignon de porc","beurre","oignons","champignons","tomates confites à l'huile","crème fraîche","cidre doux"],qty:["1 filet mignon de porc (environ 500 g)","30 g de beurre","2 oignons","150 g de champignons","100 g de tomates confites à l'huile","20 cl de crème fraîche","20 cl de cidre doux"],steps:["Faire fondre le beurre dans une sauteuse. Ajouter les oignons coupés en rondelles, puis les champignons dès qu'ils commencent à dorer.","Déposer le filet mignon dans la sauteuse et le faire dorer à feu vif environ 10 minutes sur toutes les faces. Saler et poivrer.","Ajouter la moitié du cidre, couvrir et laisser cuire à feu doux 40 minutes, en mouillant de temps en temps avec le reste du cidre et en retournant le filet mignon.","En fin de cuisson, ajouter les tomates confites égouttées, laisser cuire 5 minutes puis incorporer la crème fraîche. Rectifier l'assaisonnement.","Couper le filet mignon en tranches et servir nappé de sauce."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Couscous royal sans couscoussier (agneau, bœuf, poulet et merguez)",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:820,p:55,c:65,f:38,prep:95,ing:["côtes d'agneau","boeuf à bouillir","cuisse de poulet","merguez","oignon","carotte","navet","courgette","tomates","semoule","épices à couscous","huile d'olive"],qty:["2 côtes d'agneau","200 g de boeuf à bouillir","1 cuisse de poulet","2 merguez","1 oignon","1 carotte","1 navet","1 courgette","2 tomates","200 g de semoule moyenne","1 cuillère à soupe de chaque (cumin, coriandre, cannelle, paprika)","5 cl d'huile d'olive"],steps:["Laver et couper les légumes en morceaux de 2 à 3 cm. Émincer l'oignon et couper le boeuf en gros cubes.","Dans un fait-tout, chauffer 3 cuillères à soupe d'huile d'olive et faire revenir le boeuf, les côtes d'agneau et l'oignon jusqu'à ce que la viande soit bien saisie.","Ajouter les épices (cumin, coriandre, cannelle, paprika) et bien enrober la viande. Réserver la cuisse de poulet, couvrir le reste de viande d'eau, ajouter les navets et les carottes, saler et laisser cuire 45 minutes.","Ajouter les tomates, la courgette et la cuisse de poulet, puis poursuivre la cuisson jusqu'à ce que tout soit tendre.","Faire griller les merguez à part.","Étaler la semoule dans un plat allant au four et l'arroser de 2 cuillères à soupe d'huile d'olive en mélangeant bien.","Porter à frémissement 1 litre d'eau salée, la verser sur la semoule et laisser gonfler 5 minutes.","Égrainer la semoule à la fourchette, puis la réchauffer au four (thermostat 3) pendant 15 minutes avant de servir avec le bouillon et les viandes."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:true,sans_gluten:false,sans_fruits_a_coque:true}},
{n:"Gigot d'agneau aux pommes boulangères",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:725,p:45,c:35,f:45,prep:90,ing:["gigot d'agneau","pommes de terre","beurre","ail en chemise"],qty:["600 g","500 g","30 g","4 gousses"],steps:["Préchauffez le four à thermostat 7 (210°C).","Pelez, lavez et séchez les pommes de terre, puis taillez-les en fines rondelles à la râpe. Répartissez-les en couche régulière dans le fond du plat et parsemez de copeaux de beurre.","Déposez le gigot salé et poivré sur les pommes de terre, parsemez de thym et enfournez.","Au bout de 15 minutes, quand le gigot commence à dorer, retournez-le ; laissez cuire encore 15 minutes puis retournez-le à nouveau.","Baissez le four à thermostat 6 (180°C) et poursuivez la cuisson 40 minutes, en ajoutant les gousses d'ail en chemise durant les 30 dernières minutes.","Éteignez le four et laissez reposer le gigot 10 minutes à l'intérieur avant de servir : il sera moelleux et les pommes de terre parfumées au jus d'agneau."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Saucisses aux lentilles",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:610,p:35,c:50,f:30,prep:45,ing:["lardons fumés","carotte","lentilles vertes","saucisses","oignon blanc"],qty:["100 g","1","250 g","4","1"],steps:["Piquez les saucisses à la fourchette, puis plongez-les dans 1,5 litre d'eau froide avec un bouquet garni et la carotte coupée en rondelles. Portez à gros bouillons et laissez cuire 15 à 20 minutes.","Pendant ce temps, faites revenir les lardons à la poêle jusqu'à ce qu'ils soient dorés et croquants.","Ajoutez les lardons, l'oignon émincé et les lentilles dans la marmite avec les saucisses (inutile de saler, les lardons suffisent).","Couvrez et laissez cuire à feu doux 20 à 25 minutes.","Égouttez, retirez le bouquet garni, dressez sur un plat avec un peu de persil haché et servez aussitôt."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Boeuf bourguignon aux champignons et lardons dorés",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:600,p:45,c:15,f:40,prep:240,ing:["lardons nature","beurre","oignon","huile","carottes","farine","boeuf à bourguignon","champignons","vin rouge (bourgogne)"],qty:["50 g","25 g","1","1 cuillère à soupe","2","1 cuillère à soupe","500 g","150 g","40 cl"],steps:["Coupez la viande en gros cubes d'environ 50 g et émincez l'oignon.","Dans une cocotte, faites revenir les lardons dans l'huile et le beurre, puis réservez-les.","Faites colorer la viande à la place des lardons, ajoutez l'oignon émincé et faites revenir quelques minutes.","Pendant ce temps, coupez les carottes en rondelles fines et les champignons en quartiers.","Saupoudrez de farine, versez le vin rouge, puis ajoutez les carottes, les champignons, les lardons réservés et un bouquet garni. Salez et poivrez.","Fermez la cocotte et laissez cuire 45 minutes, puis laissez mijoter à feu doux, à couvert, encore 2 à 3 heures avant de servir."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
{n:"Curry de lotte au lait de coco",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:405,p:35,c:12,f:24,prep:30,ing:["poivron rouge","poivron vert","tomates","lotte","lait de coco","pâte de curry jaune"],qty:["1/2","1/2","2","500 g","200 ml","1 cuillère à café"],steps:["Lavez les poivrons et les tomates, coupez les tomates en quartiers et les poivrons en lamelles.","Dans une sauteuse antiadhésive ou un wok, faites revenir les poivrons et les tomates à feu moyen puis doux jusqu'à évaporation complète du jus.","Versez le lait de coco, délayez-y la pâte de curry et une pincée de sucre, puis faites chauffer doucement sans laisser bouillir.","Coupez la lotte en cubes, ajoutez-la dans la sauce coco au curry, salez et poivrez.","Laissez cuire 15 à 20 minutes à feu moyen et servez avec du riz basmati ou du riz gluant."],diet:{vegetarien:false,vegan:false,sans_poisson:false,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Gigot d'agneau rôti au romarin et à l'ail confit",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:523,p:50,c:2,f:35,prep:75,ing:["gigot d'agneau","romarin frais","ail","graisse d'oie"],qty:["800 g","2 branches","6 gousses","2 cuillères à soupe"],steps:["Préchauffez le four à thermostat 7-8 (230°C). Dégraissez le gigot à l'aide d'un couteau pour mettre la chair à vif.","Préparez une pommade en écrasant une partie de l'ail avec le romarin effeuillé, la graisse d'oie et du gros sel.","Massez le gigot avec cette pommade pour bien la faire pénétrer dans la chair.","Enfournez et arrosez toutes les 15 minutes avec un mélange d'eau chaude et de graisse.","Si vous aimez l'ail confit, glissez les gousses restantes non épluchées au fond du plat, et laissez rôtir jusqu'à la cuisson désirée, environ 45 minutes à 1 heure selon le poids."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Courgettes farcies légères",cat:"déjeuner/dîner",tags:["perte_de_poids","equilibre"],kcal:505,p:29,c:47,f:23,prep:60,ing:["courgette","boeuf haché","riz basmati","oignon","ail","coulis de tomates","parmesan","huile d'olive","thym","basilic frais"],qty:["1","200 g","100 g","1/2","1/2 gousse","100 g","15 g","1 c. à soupe","1 brin","4 feuilles"],steps:["Préchauffez le four à 200 °C. Lavez les courgettes, coupez-les en deux dans la longueur et évidez-les avec une cuillère pour former des barquettes, en réservant la chair prélevée.","Pelez et émincez l'oignon, hachez l'ail. Coupez la chair de courgette réservée en petits morceaux et ciselez le basilic.","Faites revenir l'oignon, l'ail et la chair de courgette dans l'huile d'olive quelques minutes. Ajoutez le bœuf haché et émiettez-le à la cuisson. Ajoutez le thym et le basilic, salez, poivrez, et laissez cuire jusqu'à ce que la farce soit bien cuite.","Disposez les demi-courgettes dans un plat allant au four, garnissez-les généreusement de farce et versez le coulis de tomates dessus et autour.","Enfournez environ 40 minutes, en couvrant d'une feuille de papier cuisson si les courgettes colorent trop vite.","Pendant ce temps, faites cuire le riz basmati 8 à 10 minutes dans l'eau bouillante salée, puis égouttez-le et réservez au chaud.","En fin de cuisson, parsemez les courgettes de parmesan et passez le plat sous le gril quelques instants pour gratiner. Servez avec le riz, parsemé de persil."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Salade Piémontaise facile",cat:"déjeuner/dîner",tags:["perte_de_poids","equilibre"],kcal:285,p:23,c:31,f:8,prep:35,ing:["pomme de terre","oeuf","jambon","cornichon","tomate","fromage blanc","huile","vinaigre","moutarde"],qty:["2","1 ½","125 g","4","1","2 c. à soupe","1/2 c. à café","1/2 c. à café","1/2 c. à café"],steps:["Faites cuire les pommes de terre entières, avec leur peau, dans une grande casserole d'eau salée bouillante pendant 20 minutes. Égouttez, laissez tiédir, pelez et coupez en gros dés.","Pendant ce temps, faites cuire les œufs 10 minutes dans l'eau bouillante pour les obtenir durs. Passez-les sous l'eau froide, écalez-les puis coupez-les en dés.","Coupez les tomates en deux, épépinez-les et détaillez la chair en petits cubes. Coupez les cornichons en rondelles et le jambon en dés. Réunissez le tout dans un saladier avec les pommes de terre et les œufs.","Dans un bol, mélangez le fromage blanc, l'huile, le vinaigre et la moutarde, salez, poivrez, et fouettez jusqu'à obtenir une sauce lisse et homogène.","Versez la sauce sur la salade et mélangez délicatement sans écraser les ingrédients.","Réservez au réfrigérateur au moins 1 heure avant de servir la salade bien froide."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Papillote de colin minceur",cat:"déjeuner/dîner",tags:["perte_de_poids","equilibre"],kcal:268,p:26,c:3,f:16,prep:45,ing:["filet de colin","gousse de vanille","gingembre frais","étoile de badiane","crème fraîche liquide","citron vert"],qty:["2","1","1/2 c. à soupe","1","10 cl","1"],steps:["Fendez la gousse de vanille en deux dans la longueur et grattez-en les graines.","Dans une casserole, déposez les graines et la gousse de vanille avec le gingembre, la badiane et la crème, salez, poivrez. Portez à frémissement, retirez du feu, couvrez et laissez infuser 30 minutes.","Préchauffez le four à 180 °C.","Préparez les papillotes en superposant deux feuilles de papier sulfurisé pour chacune, et déposez un filet de colin au centre de chaque papillote.","Poivrez les filets, arrosez de jus de citron vert et de la crème infusée, ajoutez une demi-gousse de vanille et une demi-étoile de badiane dans chaque papillote, puis fermez-les hermétiquement avec de la ficelle de cuisine.","Enfournez 9 à 10 minutes. Servez à la sortie du four, parsemé de fleur de sel et de poivre, accompagné de riz ou de légumes verts vapeur."],diet:{vegetarien:false,vegan:false,sans_poisson:false,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Wrap minceur",cat:"déjeuner/dîner",tags:["perte_de_poids","equilibre"],kcal:138,p:9,c:21,f:2,prep:25,ing:["pain de mie complet","jambon blanc","poivron rouge","poivron jaune","oignon","basilic","fromage blanc 0%","piment d'Espelette"],qty:["2 tranches","2 tranches","1/2","1/2","1/2","2 brins","1 c. à soupe","1/2 pincée"],steps:["Taillez les poivrons épépinés en petits dés, hachez l'oignon. Faites-les revenir 2 minutes dans une cocotte sans matière grasse, salez, poivrez. Ajoutez de l'eau tiède à mi-hauteur et laissez mijoter à couvert 15 minutes.","Aplatissez les tranches de pain de mie complet à l'aide d'un rouleau à pâtisserie.","Mélangez le fromage blanc avec le piment d'Espelette et un peu de sel, puis tartinez-en chaque tranche de pain.","Déposez une tranche de jambon blanc sur chaque tranche de pain, ajoutez le confit de poivrons et roulez serré en wraps.","Coupez les wraps en tronçons, décorez de basilic frais et servez, par exemple avec un gaspacho ou une soupe de légumes froide."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
{n:"Gratin minceur de chou-fleur sans béchamel",cat:"déjeuner/dîner",tags:["perte_de_poids","equilibre"],kcal:149,p:15,c:12,f:6,prep:55,ing:["chou-fleur","oeuf","fromage blanc","fromage râpé allégé","noix de muscade"],qty:["1/2","1","10 cl","30 g","1/2 pincée"],steps:["Détaillez le chou-fleur en fleurettes et faites-le cuire à la vapeur pendant 10 minutes, jusqu'à ce qu'il soit tendre.","Préchauffez le four à 180 °C.","Dans un saladier, fouettez les œufs avec le fromage blanc, salez, poivrez et ajoutez une pincée de muscade.","Disposez le chou-fleur dans un plat à gratin et versez l'appareil par-dessus, puis parsemez de fromage râpé allégé.","Enfournez pendant 35 minutes, jusqu'à ce que le gratin soit légèrement doré."],diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Salade tiède de lentilles et carottes rôties au cumin",cat:"déjeuner/dîner",tags:["perte_de_poids","equilibre"],kcal:255,p:13,c:40,f:6,prep:45,ing:["lentilles vertes","carotte","huile d'olive","vinaigre de cidre","cumin moulu"],qty:["100 g","2","1 c. à soupe","1/2 c. à soupe","1/2 c. à café"],steps:["Rincez les lentilles puis faites-les cuire dans une grande casserole d'eau pendant 25 minutes. Égouttez et laissez tiédir.","Épluchez les carottes et coupez-les en bâtonnets.","Disposez-les sur une plaque, arrosez-les d'une partie de l'huile d'olive, salez, poivrez et saupoudrez de cumin.","Enfournez à 180 °C pendant 30 minutes, jusqu'à ce qu'elles soient rôties et fondantes.","Dans un saladier, mélangez les lentilles et les carottes rôties, ajoutez le reste d'huile d'olive et le vinaigre de cidre.","Rectifiez l'assaisonnement et servez tiède ou froid."],diet:{vegetarien:true,vegan:true,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Papillotes minceur de cabillaud au citron",cat:"déjeuner/dîner",tags:["perte_de_poids","equilibre"],kcal:142,p:25,c:1,f:3,prep:25,ing:["dos de cabillaud","citron","huile d'olive"],qty:["2","1/2","1/2 c. à soupe"],steps:["Préchauffez le four à 180 °C.","Coupez le citron en fines rondelles.","Déposez chaque dos de cabillaud sur une feuille de papier cuisson, salez et poivrez légèrement.","Ajoutez les rondelles de citron, un filet d'huile d'olive et du persil ciselé, puis refermez les papillotes soigneusement.","Enfournez pendant 15 minutes, jusqu'à ce que le poisson soit juste nacré. Servez aussitôt."],diet:{vegetarien:false,vegan:false,sans_poisson:false,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Poêlée minceur de légumes d'hiver au gingembre",cat:"déjeuner/dîner",tags:["perte_de_poids","equilibre"],kcal:112,p:2,c:15,f:5,prep:35,ing:["carotte","poireau","panais","gingembre frais","huile d'olive"],qty:["1","1/2","1/2","1 morceau de 2 cm","1 c. à soupe"],steps:["Épluchez les carottes et le panais, puis coupez-les en bâtonnets.","Nettoyez le poireau et émincez-le. Épluchez le gingembre et râpez-le finement.","Faites chauffer l'huile d'olive dans une grande poêle, puis ajoutez les légumes et le gingembre râpé.","Salez, poivrez et faites revenir à feu moyen pendant 25 minutes en remuant régulièrement, jusqu'à ce que les légumes soient tendres et légèrement dorés.","Rectifiez l'assaisonnement avant de servir."],diet:{vegetarien:true,vegan:true,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Velouté minceur poireau-céleri sans crème",cat:"déjeuner/dîner",tags:["perte_de_poids","equilibre"],kcal:104,p:4,c:22,f:1,prep:40,ing:["poireau","branche de céleri","pomme de terre","oignon","cube de bouillon de légumes"],qty:["1 ½","1","1","1/2","1/2"],steps:["Nettoyez les poireaux et la branche de céleri, puis coupez-les en morceaux. Épluchez la pomme de terre et l'oignon, puis émincez-les.","Placez tous les légumes dans une grande casserole, ajoutez l'eau et le cube de bouillon.","Portez à ébullition puis laissez cuire à feu moyen pendant 30 minutes.","Mixez jusqu'à obtenir un velouté lisse, poivrez selon votre goût et servez bien chaud."],diet:{vegetarien:true,vegan:true,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Salade tiède light, healthy et détox au fenouil et orange",cat:"déjeuner/dîner",tags:["perte_de_poids","equilibre"],kcal:120,p:3,c:21,f:4,prep:20,ing:["fenouil","orange","huile d'olive","jus de citron"],qty:["1 bulbe","1","½ c. à soupe","½ c. à soupe"],steps:["Lavez les bulbes de fenouil, retirez la base dure et émincez-les finement.","Faites chauffer l'huile d'olive dans une poêle.","Ajoutez le fenouil et faites-le revenir 8 à 10 min à feu doux jusqu'à ce qu'il soit légèrement fondant.","Pelez les oranges à vif et coupez-les en suprêmes.","Ajoutez les oranges au fenouil hors du feu.","Arrosez de jus de citron, salez et poivrez.","Mélangez délicatement et servez tiède."],diet:{vegetarien:true,vegan:true,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Poisson vapeur détox et healthy au citron vert",cat:"déjeuner/dîner",tags:["perte_de_poids","equilibre"],kcal:135,p:22,c:2,f:4,prep:20,ing:["filet de cabillaud","citron vert","huile d'olive","coriandre fraîche"],qty:["2","1","½ c. à soupe","½ bouquet"],steps:["Râpez le zeste d'un citron vert et pressez le jus.","Disposez les filets de poisson dans un panier vapeur, salez et poivrez légèrement.","Faites cuire à la vapeur 12 à 15 min jusqu'à ce que le poisson soit nacré.","À la sortie de cuisson, arrosez de jus de citron vert et d'un filet d'huile d'olive.","Parsemez de zeste et de coriandre ciselée avant de servir."],diet:{vegetarien:false,vegan:false,sans_poisson:false,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Bowl détox, light et healthy au sarrasin et légumes rôtis",cat:"déjeuner/dîner",tags:["perte_de_poids","equilibre"],kcal:445,p:13,c:83,f:10,prep:45,ing:["sarrasin","carotte","patate douce","oignon rouge","huile d'olive","jus de citron"],qty:["150 g","2","1","½","1 c. à soupe","1 c. à soupe"],steps:["Rincez le sarrasin puis faites-le cuire dans deux fois son volume d'eau pendant 15 min. Égouttez et laissez tiédir.","Épluchez les carottes et la patate douce, puis coupez-les en cubes.","Émincez l'oignon rouge.","Disposez les légumes sur une plaque, arrosez d'huile d'olive, salez et poivrez.","Enfournez à 180 °C pendant 30 min jusqu'à ce qu'ils soient bien rôtis.","Répartissez le sarrasin dans des bols.","Ajoutez les légumes rôtis, arrosez du reste d'huile d'olive et du jus de citron.","Mélangez délicatement avant de servir."],diet:{vegetarien:true,vegan:true,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Curry light & healthy panais-épinards",cat:"déjeuner/dîner",tags:["perte_de_poids","equilibre"],kcal:255,p:4,c:30,f:11,prep:35,ing:["panais","pousses d'épinards","oignon","lait de coco léger","pâte de curry doux","huile d'olive"],qty:["1 ½","100 g","½","20 cl","½ c. à soupe","½ c. à soupe"],steps:["Épluchez les panais et coupez-les en rondelles.","Émincez l'oignon.","Faites chauffer l'huile d'olive dans une sauteuse.","Ajoutez l'oignon et laissez-le fondre à feu doux.","Incorporez la pâte de curry et mélangez pendant 1 min.","Ajoutez les panais, salez légèrement et versez le lait de coco.","Couvrez et laissez mijoter 25 min à feu doux jusqu'à ce que les panais soient tendres.","Ajoutez les pousses d'épinards en fin de cuisson et laissez-les tomber 2 à 3 min avant de servir."],diet:{vegetarien:true,vegan:true,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Soupe détox et healthy aux légumes d'hiver",cat:"déjeuner/dîner",tags:["perte_de_poids","equilibre"],kcal:125,p:3,c:28,f:0.5,prep:40,ing:["poireau","carotte","branche de céleri","pomme de terre","eau","cube de bouillon de légumes"],qty:["1","1","½","1","½ l","½"],steps:["Lavez et épluchez les légumes si nécessaire, puis coupez-les en morceaux.","Placez-les dans une grande casserole avec l'eau et le cube de bouillon.","Portez à ébullition puis laissez cuire à feu moyen pendant 30 min.","Mixez la soupe jusqu'à obtenir une texture lisse.","Poivrez selon votre goût et servez bien chaud."],diet:{vegetarien:true,vegan:true,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Poêlée détox et healthy de légumes de janvier",cat:"déjeuner/dîner",tags:["perte_de_poids","equilibre"],kcal:122,p:2,c:13,f:7,prep:30,ing:["carotte","poireau","chou-fleur","navet","huile d'olive","curcuma"],qty:["1","½","100 g","½","1 c. à soupe","½ c. à café"],steps:["Épluchez les carottes et le navet, puis coupez-les en dés.","Nettoyez le poireau et émincez-le.","Détaillez le chou-fleur en petites fleurettes.","Faites chauffer l'huile d'olive dans une grande poêle.","Ajoutez les légumes, salez, poivrez et saupoudrez de curcuma.","Faites revenir à feu moyen pendant 25 min en remuant régulièrement, jusqu'à ce que les légumes soient tendres et légèrement dorés.","Rectifiez l'assaisonnement avant de servir."],diet:{vegetarien:true,vegan:true,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Risotto healthy d'orge perlé aux champignons",cat:"déjeuner/dîner",tags:["perte_de_poids","equilibre"],kcal:360,p:13,c:55,f:11,prep:45,ing:["orge perlé","champignons de Paris","oignon","bouillon de légumes","huile d'olive","parmesan râpé"],qty:["125 g","150 g","½","½ l","1 c. à soupe","20 g"],steps:["Émincez l'oignon et nettoyez les champignons avant de les couper en lamelles.","Faites chauffer l'huile d'olive dans une grande sauteuse.","Ajoutez l'oignon et laissez-le fondre à feu doux.","Incorporez l'orge perlé et remuez 2 min pour bien l'enrober.","Ajoutez les champignons puis versez une louche de bouillon chaud.","Laissez cuire à feu doux en ajoutant le bouillon petit à petit, en remuant régulièrement, pendant 35 à 40 min.","Lorsque l'orge est tendre, ajoutez le parmesan et poivrez.","Mélangez et servez aussitôt."],diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
{n:"Bowl healthy au quinoa, panais et chou kale",cat:"déjeuner/dîner",tags:["perte_de_poids","equilibre"],kcal:345,p:9,c:55,f:11,prep:35,ing:["quinoa","panais","chou kale","huile d'olive","jus de citron"],qty:["100 g","1 ½","50 g","1 c. à soupe","½ c. à soupe"],steps:["Rincez le quinoa sous l'eau froide puis faites-le cuire dans deux fois son volume d'eau pendant 12 min. Égouttez et laissez tiédir.","Épluchez les panais et coupez-les en cubes.","Disposez-les sur une plaque, arrosez d'huile d'olive, salez et poivrez.","Enfournez à 180 °C pendant 25 min jusqu'à ce qu'ils soient dorés.","Retirez les tiges dures du chou kale et émincez les feuilles.","Massez-les avec le jus de citron et un peu d'huile d'olive pour les attendrir.","Répartissez le quinoa dans des bols, ajoutez les panais rôtis et le chou kale.","Rectifiez l'assaisonnement avant de servir."],diet:{vegetarien:true,vegan:true,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Salade healthy de lentilles, carottes rôties et grenade",cat:"déjeuner/dîner",tags:["perte_de_poids","equilibre"],kcal:350,p:16,c:44,f:12,prep:40,ing:["lentilles vertes","carotte","grenade","huile d'olive","vinaigre balsamique","cumin moulu","feta"],qty:["100 g","2","½","1 c. à soupe","½ c. à soupe","½ c. à café","40 g"],steps:["Rincez les lentilles puis faites-les cuire dans une grande casserole d'eau non salée pendant 25 min. Égouttez-les et laissez-les refroidir.","Épluchez les carottes et coupez-les en bâtonnets.","Déposez-les sur une plaque, arrosez d'huile d'olive, salez, poivrez et saupoudrez de cumin.","Enfournez à 180 °C pendant 30 min jusqu'à ce qu'elles soient tendres et légèrement rôties.","Coupez la grenade en deux et récupérez les graines.","Dans un saladier, mélangez les lentilles, les carottes rôties et les graines de grenade.","Assaisonnez avec le reste d'huile d'olive et le vinaigre balsamique, rectifiez l'assaisonnement et servez avec la feta émiettée."],diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Curry healthy de légumes racines et lait de coco",cat:"déjeuner/dîner",tags:["perte_de_poids","equilibre"],kcal:270,p:4,c:35,f:11,prep:45,ing:["carotte","panais","patate douce","oignon","lait de coco léger","pâte de curry doux","huile de coco"],qty:["1","1","1/2","1/2","20 cl","1/2 c. à soupe","1/2 c. à soupe"],steps:["Épluchez les légumes racines et coupez-les en cubes.","Émincez l'oignon.","Faites chauffer l'huile de coco dans une grande sauteuse.","Ajoutez l'oignon et laissez-le fondre quelques minutes.","Incorporez la pâte de curry et mélangez.","Ajoutez les légumes, salez légèrement et versez le lait de coco.","Couvrez et laissez mijoter à feu doux pendant 30 min jusqu'à ce que les légumes soient tendres.","Mélangez délicatement avant de servir."],diet:{vegetarien:true,vegan:true,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Soupe de poulet healthy",cat:"déjeuner/dîner",tags:["perte_de_poids","equilibre"],kcal:330,p:26,c:50,f:4,prep:25,ing:["blanc de poulet","bouillon de volaille","oignon","nouilles plates","carotte"],qty:["1","50 cl","1/2","125 g","1/2"],steps:["Détaillez le poulet en lanières, coupez la carotte épluchée en rondelles fines et émincez l'oignon.","Dans un faitout, faites chauffer l'huile, faites fondre l'oignon et la carotte pendant 2 min, ajoutez le poulet et versez le bouillon. Salez, poivrez.","Portez à ébullition, ajoutez les nouilles et laissez frémir le temps indiqué sur le paquet.","Dégustez bien chaud parsemé de persil ciselé."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:true,sans_gluten:false,sans_fruits_a_coque:true}},
{n:"Courgette minceur",cat:"déjeuner/dîner",tags:["perte_de_poids","equilibre"],kcal:127,p:2,c:7,f:11,prep:40,ing:["courgette","oignon frais","pousses de salade variées","citron","huile d'olive"],qty:["2","2","quelques brins","1/2","2 c. à soupe"],steps:["Rincez et essuyez les courgettes, coupez les extrémités et taillez-les en tout petits dés sans les peler.","Pelez et hachez les oignons frais, ajoutez-les aux courgettes. Assaisonnez de fleur de sel et de poivre, arrosez de jus de citron et d'huile d'olive, mélangez bien.","Couvrez d'un film étirable et réservez 30 min au frais.","Dressez dans des assiettes à l'aide de cercles de présentation et décorez de quelques brins de pousses de salade."],diet:{vegetarien:true,vegan:true,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Clafoutis salé minceur",cat:"déjeuner/dîner",tags:["perte_de_poids","equilibre"],kcal:235,p:10,c:18,f:14,prep:55,ing:["lait écrémé","tomate cerise jaune","courgette","oignon jaune","ail","farine","ricotta","huile d'olive","oeuf"],qty:["12,5 cl","5","1/2","1/2","1/2 gousse","25 g","25 g","1,5 c. à soupe","1,5"],steps:["Préchauffez le four à 200 °C. Lavez les légumes, coupez la courgette en fines rondelles et ciselez finement l'oignon et l'ail.","Faites-les poêler dans la moitié de l'huile jusqu'à ce qu'ils blondissent, mélangez avec les tomates cerises et placez le tout dans un plat à gratin.","Dans un saladier, fouettez les œufs avec le reste d'huile, ajoutez la farine, salez, poivrez et incorporez la ricotta.","Délayez avec le lait tout en fouettant, puis versez cette préparation sur les légumes.","Enfournez pour 40 min, puis laissez refroidir pour servir froid ou tiède en entrée."],diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
{n:"Salade de légumes minceur en verrine",cat:"déjeuner/dîner",tags:["perte_de_poids","equilibre"],kcal:114,p:2,c:5,f:10,prep:15,ing:["courgette","fenouil","concombre","tomate cerise","huile d'olive","jus de citron"],qty:["1/2","1/4 bulbe","1/4","75 g","2 c. à soupe","1/2 c. à soupe"],steps:["Lavez la courgette, le fenouil et les tomates cerises, ôtez les extrémités et épluchez le concombre.","Coupez les tomates cerises en deux, taillez le fenouil et le concombre en dés, tranchez la courgette en fines lanières.","Mélangez tous les légumes dans un saladier, arrosez de jus de citron et d'huile d'olive, salez, poivrez et mélangez.","Dressez dans de jolies verrines avant de servir."],diet:{vegetarien:true,vegan:true,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Velouté minceur de patate douce et carottes au curry (Cookeo)",cat:"déjeuner/dîner",tags:["perte_de_poids","equilibre"],kcal:101,p:2,c:21,f:1,prep:30,ing:["patate douce","carotte","bouillon de volaille","curry"],qty:["1/2","1/2 botte","1/2 tablette","1/2 c. à café"],steps:["Épluchez la patate douce et les carottes, rincez-les et coupez-les en morceaux.","Déposez les légumes dans la cuve du Cookeo, ajoutez le bouillon de volaille émietté, salez peu, poivrez, saupoudrez de curry et couvrez d'eau juste à hauteur.","Faites cuire en mode « sous pression » pendant 15 min.","Mixez et servez bien chaud."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Salade healthy rapide pas cher",cat:"déjeuner/dîner",tags:["perte_de_poids","equilibre"],kcal:152,p:9,c:4,f:12,prep:10,ing:["coeur de laitue","tomate","thon","olives vertes","huile d'olive"],qty:["1/2","1","1/2 boîte","1/2 petit bocal","1,5 c. à soupe"],steps:["Rincez et essorez les feuilles de salade, lavez les tomates et coupez-les en tranches, égouttez et effilochez le thon.","Répartissez les feuilles de salade dans chaque assiette, ajoutez les tranches de tomate et le thon, parsemez d'olives, salez peu, poivrez, arrosez d'un filet d'huile et servez frais."],diet:{vegetarien:false,vegan:false,sans_poisson:false,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Gratin de légumes healthy",cat:"déjeuner/dîner",tags:["perte_de_poids","equilibre"],kcal:246,p:8,c:34,f:9,prep:55,ing:["poivron orange","poivron rouge","courgette","pomme de terre","brocoli","oignon blanc","bouillon de légumes","huile d'olive","fromage râpé"],qty:["1/2","1/2","1/2","2","4 fleurons","1/2","10 cl","1 c. à soupe","20 g"],steps:["Lavez les poivrons, coupez-les en deux, ôtez les pédoncules, les graines et les côtes blanches puis taillez la chair en morceaux.","Lavez la courgette, éliminez les extrémités, coupez-la en deux dans la longueur puis en tranches.","Lavez les fleurons de brocoli, épluchez l'oignon blanc et émincez-le, pelez les pommes de terre et coupez-les en tranches.","Mettez l'ensemble des légumes dans un plat à gratin, mélangez-les, mouillez avec le bouillon de légumes, arrosez d'huile d'olive, salez et poivrez.","Enfournez à 200 °C pendant 35 minutes.","Saupoudrez de fromage râpé et enfournez sous le grill pendant 5 minutes."],diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Tzatziki minceur",cat:"déjeuner/dîner",tags:["perte_de_poids","equilibre"],kcal:69,p:3,c:3,f:5,prep:75,ing:["concombre","petit-suisse 0%","ail","huile d'olive","coriandre"],qty:["1/2","3","1 gousse","1 c. à soupe","3 brins"],steps:["Rincez et essuyez le concombre, pelez-le en éliminant une bande de peau sur deux, coupez-le en deux dans la longueur, ôtez les graines puis râpez chaque moitié au-dessus d'une passoire.","Saupoudrez de sel et laissez dégorger 1 h.","Mélangez les petits-suisses avec l'ail pelé et pressé, l'huile d'olive et la coriandre ciselée. Salez, poivrez.","Égouttez le concombre en le pressant dans les mains par petites quantités, ajoutez-le au fur et à mesure dans la sauce.","Couvrez et réservez au réfrigérateur jusqu'au moment de servir."],diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Salade minceur aux quatre saveurs",cat:"déjeuner/dîner",tags:["perte_de_poids","equilibre"],kcal:173,p:1.5,c:28,f:6.7,prep:15,ing:["salade 4 saveurs","pomme granny smith","raisin blanc","échalote","olives noires","huile d'olive","vinaigre de cidre"],qty:["1/2 sachet","1 ½","1/2 grappe","1","25 g","1 c. à soupe","1/2 c. à soupe"],steps:["Lavez et coupez les pommes en quartiers, épluchez et émincez l'échalote.","Mélangez la salade 4 saveurs, les pommes, le raisin, l'échalote et les olives dans un saladier.","Ajoutez l'huile d'olive et le vinaigre de cidre, salez, poivrez et mélangez bien avant de servir."],diet:{vegetarien:true,vegan:true,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Soupe de légumes carotte, poireau et céleri",cat:"déjeuner/dîner",tags:["perte_de_poids","equilibre"],kcal:41,p:1.6,c:6.1,f:0.2,prep:55,ing:["carotte","poireau","branche de céleri","oignons nouveaux"],qty:["1","1/2","1/2","1/2 botte"],steps:["Épluchez et rincez les carottes, coupez-les en rondelles épaisses. Épluchez et lavez le poireau, coupez-le en morceaux. Lavez la branche de céleri et coupez-la en tronçons. Pelez les oignons nouveaux en conservant les tiges vertes et ciselez-les.","Déposez tous les légumes dans une grande casserole, couvrez largement d'eau, salez, poivrez et portez à ébullition. Laissez cuire doucement pendant 45 minutes.","Filtrez le bouillon et versez-le dans des bols. Parsemez de persil et servez."],diet:{vegetarien:true,vegan:true,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Velouté minceur de fanes de radis et pomme de terre",cat:"déjeuner/dîner",tags:["perte_de_poids","equilibre"],kcal:48,p:2.3,c:9.3,f:0.4,prep:30,ing:["fanes de radis","pomme de terre","courgette","bouillon de volaille","piment d'Espelette"],qty:["1 botte","1/2","1/2","1/2 tablette","1/2 pincée"],steps:["Rincez soigneusement les fanes de radis. Pelez la pomme de terre, lavez-la et coupez-la en morceaux. Rincez la courgette et coupez-la en tronçons.","Mettez tous les légumes dans une marmite, ajoutez la tablette de bouillon, salez, puis recouvrez d'eau à hauteur. Portez à ébullition et laissez mijoter environ 20 minutes.","Mixez le tout et versez dans des assiettes. Parsemez de piment d'Espelette et servez bien chaud."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Cataplana healthy",cat:"déjeuner/dîner",tags:["perte_de_poids","equilibre"],kcal:275,p:23.3,c:29.8,f:7.1,prep:30,ing:["pomme de terre","poivron rouge","courgette","tomate","filet de lieu jaune","moules décoquillées","petites crevettes","oignon","ail","huile","bouillon"],qty:["1 ½","1/2","1/2","1","1","75 g","50 g","1/2","1 gousse","1 c. à soupe","10 cl"],steps:["Pelez les pommes de terre et coupez-les en dés. Épluchez et émincez l'oignon et l'ail. Rincez la courgette et détaillez-la en rondelles. Rincez et coupez le poivron et les tomates en dés.","Faites chauffer l'huile dans une grande poêle. Faites revenir l'oignon et les pommes de terre pendant environ 5 minutes. Ajoutez les dés de poivron et de tomates, les rondelles de courgette et l'ail, puis incorporez le bouillon. Portez à ébullition, couvrez et laissez cuire pendant 20 minutes.","Ajoutez les filets de poisson, les moules et les crevettes, puis poursuivez la cuisson pendant 5 minutes.","Salez, poivrez, parsemez de persil ciselé et servez."],diet:{vegetarien:false,vegan:false,sans_poisson:false,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Purée d'aubergine minceur",cat:"déjeuner/dîner",tags:["perte_de_poids","equilibre"],kcal:40,p:1.7,c:9.2,f:0.3,prep:40,ing:["aubergine","concentré de tomate","cumin en poudre","curcuma en poudre"],qty:["1","1 c. à soupe","1/2 c. à café","1/4 c. à café"],steps:["Déposez les aubergines dans le panier du cuit-vapeur ou dans un panier vapeur de cocotte. Laissez cuire entre 30 et 35 minutes.","Coupez la chair en gros morceaux et placez-la dans le bol d'un robot avec le concentré de tomates et les épices.","Salez et poivrez puis mixez finement."],diet:{vegetarien:true,vegan:true,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Curry de légumes healthy",cat:"déjeuner/dîner",tags:["perte_de_poids","equilibre"],kcal:258,p:8.4,c:29.3,f:12.1,prep:40,ing:["tomates concassées","bouillon de légumes","chou-fleur","pois chiches","carotte","haricots verts surgelés","ail","oignon","gingembre","coriandre en poudre","curcuma","cumin en poudre","garam masala","curcuma fumé","coriandre fraîche","huile"],qty:["1/2 boite","20 cl","120 g","1/2 petite boite","1","60 g","1 gousse","1/2","1 cm","1 ½ c. à café","1/2 c. à moka","1/2 c. à café","1 ½ c. à café","1 c. à café","2 branches","2 c. à soupe"],steps:["Épluchez et ciselez l'oignon. Pressez l'ail pour en récupérer la pulpe. Pelez et râpez le gingembre.","Pelez les carottes, éliminez les extrémités et taillez-les en rondelles.","Plongez les haricots verts dans une casserole d'eau bouillante salée et faites-les cuire 5 minutes, puis rafraîchissez-les et égouttez-les.","Dans une sauteuse, faites revenir l'oignon, l'ail, le gingembre et les épices dans l'huile sur feu moyen-fort pendant 5 minutes en mélangeant régulièrement.","Ajoutez les tomates concassées, le bouillon de légumes, les rondelles de carottes et les fleurons de chou-fleur. Baissez le feu et laissez mijoter 20 minutes.","Ajoutez les pois chiches et les haricots verts, puis poursuivez la cuisson 5 minutes.","Servez le curry et parsemez de coriandre fraîche."],diet:{vegetarien:true,vegan:true,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Tian minceur",cat:"déjeuner/dîner",tags:["perte_de_poids","equilibre"],kcal:140,p:7.3,c:22,f:2.8,prep:90,ing:["courgette","tomate","oignon","ail","basilic frais","feuille de laurier","huile d'olive"],qty:["1 kg","1 ½","1/2","1 ½ gousses","1/2 bouquet","1/2","1/2 filet"],steps:["Lavez les courgettes sans les peler, ôtez les extrémités puis coupez-les en fines tranches. Coupez également les tomates en fines tranches.","Pelez et émincez l'oignon et l'ail, faites-les revenir dans une poêle avec un filet d'huile d'olive pendant 5 minutes à feu moyen. Versez le tout dans le fond d'un plat à four.","Préchauffez le four à 160°C. Rangez les tranches de légumes dans le plat, verticalement, en les alternant au maximum. Ajoutez la feuille de laurier, salez et poivrez généreusement.","Arrosez d'un filet d'huile d'olive, couvrez d'une feuille de papier aluminium et enfournez pour 1h10.","Servez avec le basilic fraîchement effeuillé."],diet:{vegetarien:true,vegan:true,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Méli-mélo de légumes minceur en papillote",cat:"déjeuner/dîner",tags:["perte_de_poids","equilibre"],kcal:140,p:1.8,c:6.8,f:10.2,prep:30,ing:["carotte","courgette","huile d'olive"],qty:["2","1","2 c. à soupe"],steps:["Préchauffez le four à 200°C.","Épluchez les carottes, rincez les courgettes. Coupez les extrémités des légumes et taillez-les en tranches fines dans la longueur à la mandoline. Mélangez-les dans un saladier avec l'huile d'olive, du sel et du poivre.","Disposez les légumes sur de grands cercles de papier sulfurisé et refermez en serrant bien.","Déposez les papillotes sur une plaque allant au four et enfournez 15 minutes. Servez bien chaud."],diet:{vegetarien:true,vegan:true,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Bowl hivernal quinoa, betterave et avocat",cat:"déjeuner/dîner",tags:["perte_de_poids","equilibre"],kcal:221,p:4.1,c:17.8,f:15.1,prep:30,ing:["chou rouge","avocat","carotte","quinoa","houmous","betterave chioggia","graines de tournesol","moutarde douce","vinaigre de xérès","huile d'olive","jus de citron","menthe fraîche"],qty:["60 g","1/2","1","20 g","1 c. à soupe","1/2","1/2 c. à café","1/2 c. à café","1/2 c. à soupe","1 ½ c. à soupe","1/2 c. à café","1/2 branche"],steps:["Pelez les carottes, éliminez les extrémités puis taillez la chair en lanières à l'aide d'un économe.","Lavez et émincez le chou rouge.","Pelez la betterave puis taillez-la en fines tranches régulières à la mandoline.","Faites cuire le quinoa dans deux fois son volume d'eau bouillante salée pendant 10 minutes.","Coupez l'avocat en deux, ôtez le noyau, récupérez la chair à la cuillère et taillez-la en tranches. Citronnez légèrement pour éviter l'oxydation.","Dans un bol, mélangez la moutarde avec le vinaigre, du sel et du poivre. Ajoutez l'huile d'olive petit à petit en fouettant.","Répartissez tous les ingrédients dans deux bols.","Assaisonnez de vinaigrette.","Décorez de graines de tournesol et de quelques feuilles de menthe."],diet:{vegetarien:true,vegan:true,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Carrés de cabillaud minceur",cat:"déjeuner/dîner",tags:["perte_de_poids","equilibre"],kcal:146,p:22,c:1,f:6,prep:15,ing:["cabillaud","beurre","olives vertes","câpres","thym","baies roses concassées"],qty:["2 pavés","10 g","1 c. à soupe","½ c. à soupe","½ brin","½ pincée"],steps:["Dans une poêle, faire mousser le beurre avec le brin de thym.","Faire dorer les pavés de cabillaud 3 minutes de chaque côté.","Saler, poivrer, puis ajouter les câpres et les olives hachées.","Servir aussitôt en parsemant le poisson de baies roses concassées."],diet:{vegetarien:false,vegan:false,sans_poisson:false,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Poke bowl riz, avocat et œuf au plat",cat:"déjeuner/dîner",tags:["perte_de_poids","equilibre"],kcal:485,p:14,c:55,f:24,prep:20,ing:["riz blanc","oeuf","huile d'olive","avocat","citron vert","sauce soja","graines mélangées","coriandre fraîche"],qty:["125 g","2","1 ½ c. à soupe","½","½","2 c. à soupe","1 poignée","quelques pluches"],steps:["Cuire le riz dans un grand volume d'eau bouillante salée, puis égoutter.","Couper l'avocat en deux, retirer le noyau et la peau, citronner et détailler en fines tranches.","Dans une poêle, réchauffer doucement le riz avec une cuillère d'huile d'olive, ajouter la sauce soja et un peu de coriandre, mélanger.","Dans une seconde poêle avec le reste d'huile d'olive, cuire les œufs au plat.","Dresser le riz, l'avocat et l'œuf au plat dans chaque assiette creuse, parsemer de graines mélangées et de coriandre, poivrer."],diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:true,sans_gluten:false,sans_fruits_a_coque:true}},
{n:"Bowl hivernal roquette, pamplemousse et tartines avocat-fromage frais",cat:"déjeuner/dîner",tags:["perte_de_poids","equilibre"],kcal:131,p:3,c:12,f:9,prep:15,ing:["roquette","pamplemousse","wasa (biscotte suédoise)","fromage frais","avocat","mélange de graines","citron vert","huile d'olive"],qty:["15 g","¼","1","1 c. à soupe","¼","½ poignée","¼","1 filet"],steps:["Étaler le fromage frais sur chaque Wasa, puis écraser l'avocat à la fourchette par-dessus.","Arroser de jus de citron vert et saupoudrer de graines mélangées.","Peler le pamplemousse à vif avec un couteau bien aiguisé et le détailler en rondelles.","Dans une assiette creuse, déposer la roquette arrosée d'un filet d'huile d'olive, ajouter les rondelles de pamplemousse et les tartines."],diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
{n:"Salade healthy au quinoa, légumes et framboises",cat:"déjeuner/dîner",tags:["perte_de_poids","equilibre"],kcal:155,p:4,c:20,f:6,prep:15,ing:["quinoa","concombre","champignon de Paris","tomates cerises","oignon rouge","framboises","huile d'olive","citron jaune","graines mélangées"],qty:["50 g","2 ½ rondelles","1","2 ½","¼","2","½ c. à soupe","jus de ¼","½ c. à soupe"],steps:["Cuire le quinoa selon les indications du paquet, puis rincer et réserver.","Dans un bol, mélanger le quinoa avec les légumes coupés et les framboises.","Ajouter l'huile d'olive et le jus de citron, saler, poivrer, parsemer de graines et mélanger."],diet:{vegetarien:true,vegan:true,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Blinis healthy d'épinard au saumon fumé et à l'avocat (IG bas)",cat:"déjeuner/dîner",tags:["perte_de_poids","equilibre"],kcal:461,p:12,c:33,f:33,prep:90,ing:["farine de blé","farine de sarrasin","oeuf","levure fraîche de boulanger","lait tiède","sucre en poudre","jeunes pousses d'épinard","saumon fumé","avocat","crème fleurette","baies roses","aneth","jus de citron"],qty:["35 g","15 g","½","2 g","12 ½ cl","½ pincée","50 g","1 ½ tranches","1 ½","7 ½ cl","½ c. à café","1 ½ branches","1 c. à soupe"],steps:["Délayer la levure fraîche avec une pincée de sucre dans 10 cl de lait tiède, laisser fermenter 15 minutes à température ambiante.","Séparer le blanc du jaune d'œuf.","Laver et essorer les jeunes pousses d'épinard.","Mixer au blender la levure délayée avec le reste du lait, les épinards et le jaune d'œuf.","Ajouter les farines et une pincée de sel, mélanger jusqu'à obtenir une pâte homogène.","Verser la pâte dans un saladier, couvrir d'un torchon propre et laisser reposer 1 heure à température ambiante.","Monter le blanc d'œuf en neige au batteur électrique.","Incorporer délicatement le blanc en neige à la pâte à l'aide d'une maryse.","Chauffer une poêle antiadhésive à feu vif, déposer des petits tas de pâte pour former des disques réguliers de 6 à 7 cm.","Cuire chaque blini environ 1 minute d'un côté puis 30 secondes de l'autre.","Monter la crème fleurette bien froide en chantilly au batteur électrique.","Couper le saumon fumé en morceaux et les avocats en tranches, en les citronnant légèrement pour éviter l'oxydation.","Garnir les blinis d'avocat, de saumon fumé, de chantilly, de pluches d'aneth et de baies roses. Saler, poivrer."],diet:{vegetarien:false,vegan:false,sans_poisson:false,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
{n:"Smoothie d'hiver healthy au kiwi, pomme et citron",cat:"petit-déjeuner",tags:["perte_de_poids","equilibre"],kcal:52,p:1,c:13,f:0.5,prep:10,ing:["kiwi","pomme","citron non traité","eau froide","miel"],qty:["1","½","½","10 cl","½ c. à café"],steps:["Éplucher les kiwis et les couper en morceaux.","Laver la pomme, retirer le cœur et la couper en dés.","Râper finement le zeste du citron puis presser le jus.","Placer les fruits dans le bol du blender.","Ajouter l'eau froide, le jus et le zeste de citron, ainsi que le miel.","Mixer jusqu'à obtenir un smoothie lisse et homogène.","Servir immédiatement bien frais."],diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Pancakes healthy aux pommes sans oeufs et sans lait",cat:"petit-déjeuner",tags:["perte_de_poids","equilibre"],kcal:420,p:7,c:63,f:14,prep:80,ing:["farine","levure chimique","sucre de canne","beurre","cannelle","compote de pommes","lait d'amande","huile de tournesol"],qty:["125 g","½ sachet","25 g","20 g","½ c. à café","35 g","22,5 cl","quantité suffisante"],steps:["Verser les ingrédients secs (farine, levure, sucre, cannelle) dans un saladier.","Creuser un puits et ajouter la compote puis le lait d'amande petit à petit en mélangeant.","Incorporer la farine progressivement en évitant les grumeaux, puis ajouter le beurre fondu.","Laisser reposer la pâte homogène pendant 1 heure.","Huiler légèrement une poêle à pancakes et faire chauffer à feu vif.","Verser une louche de pâte dans la poêle pour former un pancake.","Laisser cuire environ 1 minute jusqu'à apparition de bulles, puis retourner.","Cuire encore 1 minute sur l'autre face puis réserver.","Répéter l'opération jusqu'à épuisement de la pâte."],diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:false}},
{n:"Crêpes healthy à la farine d'épeautre",cat:"petit-déjeuner",tags:["perte_de_poids","equilibre"],kcal:616,p:27,c:94,f:18,prep:25,ing:["farine d'épeautre","oeufs","huile de pépins de raisin","lait","eau"],qty:["250 g","1½","12,5 g","250 ml","250 ml"],steps:["Mélanger le lait et l'eau.","Dans un cul de poule, mélanger la farine avec les œufs, l'huile et le sel.","Incorporer progressivement le mélange lait/eau pour éviter les grumeaux.","Mixer au mixeur plongeant si des grumeaux persistent.","Huiler légèrement la poêle et la faire chauffer à feu moyen.","Verser une louche de pâte et bien répartir dans la poêle.","Cuire 1 à 2 minutes, retourner la crêpe et cuire encore 1 minute.","Réserver au chaud sous une feuille d'aluminium.","Répéter jusqu'à épuisement de la pâte.","Servir chaud, tiède ou froid."],diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
{n:"Muffins express à la banane et aux framboises, 100% healthy",cat:"petit-déjeuner",tags:["perte_de_poids","equilibre"],kcal:73,p:4,c:9,f:3,prep:20,ing:["banane","oeufs","framboises"],qty:["½","1","7-8"],steps:["Préchauffer le four à 200°C.","Éplucher la banane et l'écraser à la fourchette.","Ajouter l'œuf et mélanger pour obtenir l'appareil à muffins.","Graisser le moule à muffins.","Répartir 2 à 3 framboises dans chaque empreinte.","Recouvrir avec l'appareil banane-œuf.","Tapoter légèrement le moule pour tasser la préparation.","Enfourner 12 minutes, ajuster la cuisson selon le four.","Laisser refroidir avant de démouler.","Décorer d'une framboise fraîche avant de servir."],diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Barre de céréales healthy",cat:"petit-déjeuner",tags:["perte_de_poids","equilibre"],kcal:535,p:10,c:80,f:21,prep:30,ing:["amarante","flocons d'avoine","cranberries séchées","sirop d'érable","beurre"],qty:["50 g","75 g","50 g","55 g","40 g"],steps:["Faire chauffer le sirop d'érable avec le beurre coupé en dés dans une casserole.","Mélanger l'amarante, les flocons d'avoine et les cranberries dans un saladier.","Verser le mélange sirop d'érable/beurre et bien mélanger.","Préchauffer le four à 160°C, verser la préparation dans un cadre à pâtisserie sur une plaque recouverte de papier cuisson.","Enfourner environ 20 minutes.","Laisser refroidir, démouler et découper en barres."],diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
{n:"Gaufre healthy",cat:"petit-déjeuner",tags:["perte_de_poids","equilibre"],kcal:170,p:4,c:28,f:4,prep:20,ing:["farine","compote de pomme sans sucre ajouté","levure chimique","lait d'amande","huile neutre"],qty:["70 g","15 g","1½ g","10 cl","½ c. à soupe"],steps:["Tamiser la farine et la levure chimique dans un saladier.","Ajouter le sel et mélanger les poudres.","Ajouter la compote puis le lait d'amande petit à petit en mélangeant jusqu'à obtenir une pâte homogène.","Déposer un peu de pâte sur les plaques chaudes et huilées du gaufrier.","Cuire environ 4 minutes par gaufre et répéter jusqu'à épuisement de la pâte."],diet:{vegetarien:true,vegan:true,sans_poisson:true,sans_lactose:true,sans_gluten:false,sans_fruits_a_coque:false}},
{n:"Banana bread healthy",cat:"petit-déjeuner",tags:["perte_de_poids","equilibre"],kcal:526,p:12,c:68,f:24,prep:120,ing:["banane","sucre cassonade","yaourt","huile neutre","oeufs","farine","poudre d'amande","levure chimique","citron jaune","beurre pour le moule","farine pour le moule"],qty:["1½","40 g","20 g","2 cl","1","60 g","40 g","½ sachet","½","2,5 g","1 c. à soupe"],steps:["Prélever le zeste et le jus du citron.","Éplucher les bananes et écraser la chair à la fourchette.","Ajouter le sucre, une cuillère à soupe de jus de citron et le zeste, puis laisser mariner 1 heure à température ambiante.","Ajouter le yaourt, l'huile et l'œuf aux bananes écrasées et mélanger.","Dans un saladier, tamiser la farine, la levure et la poudre d'amande, puis ajouter une pincée de sel.","Incorporer la préparation à base de bananes aux poudres et mélanger au fouet jusqu'à obtenir une pâte homogène.","Beurrer et fariner un moule à cake, puis y verser la pâte.","Disposer quelques rondelles de banane à la surface.","Enfourner à 180°C pendant 45 minutes.","Laisser refroidir avant de démouler."],diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:false}},
{n:"Coupe de fruits / muesli minceur",cat:"petit-déjeuner",tags:["perte_de_poids","equilibre"],kcal:587,p:15,c:91,f:20,prep:10,ing:["yaourt grec","groseilles","muesli","miel liquide"],qty:["2 1/2","150 g","150 g","3 c. à soupe"],steps:["Verser les yaourts grecs dans un saladier avec le miel liquide et mélanger ; réserver au frais.","Égrainer les groseilles en réservant quelques grappes pour la décoration.","Répartir le miel dans des verres, puis alterner des couches de groseilles, de muesli et de yaourt au miel.","Décorer avec une grappe de groseilles et servir aussitôt."],diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
{n:"Crêpe minceur",cat:"petit-déjeuner",tags:["perte_de_poids","equilibre"],kcal:325,p:7,c:52,f:9,prep:15,ing:["maïzena","lait","oeuf","édulcorant","beurre"],qty:["100 g","25 cl","1","10 g","5 g"],steps:["Verser la Maïzena tamisée et l'édulcorant dans un saladier avec une pincée de sel.","Ajouter l'œuf battu et mélanger au fouet.","Verser le lait en filet en mélangeant pour éviter les grumeaux.","Faire fondre une noisette de beurre dans une poêle chaude et verser une louche de pâte.","Faire dorer les crêpes environ 1 minute de chaque côté."],diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Pancakes healthy aux bananes, graines de chia et myrtilles",cat:"petit-déjeuner",tags:["perte_de_poids","equilibre"],kcal:197,p:8,c:22,f:9.5,prep:15,ing:["oeuf","banane mûre","graines de chia","amarante","myrtilles","huile neutre"],qty:["2","1","1 c. à soupe","5 g","1/2 barquette","2 c. à soupe"],steps:["Battre les œufs dans un saladier.","Écraser la banane à la fourchette jusqu'à obtenir une purée.","Incorporer la purée de banane aux œufs battus.","Ajouter les graines de chia et l'amarante, mélanger jusqu'à obtenir une pâte homogène.","Chauffer une poêle antiadhésive légèrement huilée à feu vif.","Verser un peu de pâte et former des disques à la cuillère, cuire 1 à 2 minutes par face.","Répéter avec le reste de pâte, laver les myrtilles et en garnir les pancakes."],diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Pancakes healthy aux fruits rouges",cat:"petit-déjeuner",tags:["perte_de_poids","equilibre"],kcal:369,p:11,c:65,f:7,prep:45,ing:["yaourt brassé","farine","oeuf","levure chimique","framboises","fraises","miel liquide"],qty:["150 g","100 g","1","1/2 sachet","1/2 barquette","1/2 barquette","2 c. à soupe"],steps:["Mélanger au fouet les œufs et le yaourt dans un saladier.","Ajouter petit à petit la farine tamisée, la levure chimique et le sel jusqu'à obtenir une pâte homogène.","Couvrir et laisser reposer 30 minutes à température ambiante.","Chauffer une poêle antiadhésive à feu moyen et cuire les pancakes à la louche, environ 2 min 30 par face.","Laver les fruits rouges et couper les fraises en quartiers.","Servir les pancakes avec les fruits rouges, du yaourt et du miel."],diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
{n:"Granola maison healthy",cat:"petit-déjeuner",tags:["perte_de_poids","equilibre"],kcal:670,p:24,c:50,f:45,prep:35,ing:["flocons d'avoine","noix de cajou","noisettes","mélange de graines","jus de pomme","huile d'olive"],qty:["100 g","50 g","50 g","50 g","4 cl","1/2 c. à soupe"],steps:["Mélanger les flocons d'avoine, les noix de cajou, les noisettes, le mélange de graines, le jus de pomme, l'huile d'olive et le sel dans un saladier.","Étaler la préparation sur une plaque recouverte de papier cuisson.","Enfourner à 170°C pendant 30 minutes en mélangeant toutes les 10 minutes.","Laisser refroidir puis conserver dans un bocal hermétique."],diet:{vegetarien:true,vegan:true,sans_poisson:true,sans_lactose:true,sans_gluten:false,sans_fruits_a_coque:false}},
{n:"Muffins healthy pomme cannelle",cat:"petit-déjeuner",tags:["perte_de_poids","equilibre"],kcal:282,p:10,c:50,f:6.5,prep:30,ing:["pomme","farine (sarrasin et blé)","oeuf","sirop d'agave","fromage blanc 0%","purée d'amandes","extrait de vanille","cannelle","levure"],qty:["1","75 g","1/2","1 c. à soupe","50 ml","1 c. à soupe","1/4 c. à café","1/4 c. à café","1/2 sachet"],steps:["Séparer le blanc du jaune d'œuf.","Monter le blanc en neige avec une pincée de sel et réserver.","Fouetter le jaune avec le sirop d'agave, le fromage blanc, la purée d'amandes, l'extrait de vanille et l'eau tiède.","Ajouter la farine et la cannelle, mélanger puis incorporer la levure.","Couper la pomme en petits dés et l'ajouter à la préparation.","Incorporer délicatement le blanc en neige.","Répartir dans des moules à muffins remplis aux trois quarts, saupoudrer de flocons d'avoine.","Enfourner 15 à 20 minutes à 200°C et vérifier la cuisson à la lame de couteau."],diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:false}},
{n:"Galette des rois healthy aux amandes complètes",cat:"dessert",tags:["perte_de_poids","equilibre"],kcal:880,p:17,c:55,f:66,prep:45,ing:["Pâte feuilletée complète","Poudre d'amandes complètes","Miel","Huile de coco","Oeufs"],qty:["1 pâte (2 abaisses)","75 g","40 g","40 g","1"],steps:["Préchauffer le four à 180°C et dérouler une pâte feuilletée sur une plaque, piquer le centre à la fourchette.","Fouetter les œufs avec le miel dans un saladier.","Ajouter l'huile de coco fondue puis la poudre d'amandes, mélanger jusqu'à obtenir une crème épaisse.","Étaler la garniture sur la pâte en laissant une bordure libre, ajouter la fève.","Recouvrir avec la seconde pâte, souder les bords, dorer, rayer et percer un trou au centre.","Enfourner 30 minutes jusqu'à ce que la galette soit bien dorée."],diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:false}},
{n:"Cookies healthy aux pépites de chocolat et flocons d'avoine",cat:"dessert",tags:["perte_de_poids","equilibre"],kcal:890,p:15,c:119,f:40,prep:30,ing:["Farine","Flocons d'avoine","Sucre roux","Beurre","Pépites de chocolat","Bicarbonate de soude","Oeufs","Fleur de sel"],qty:["120 g","60 g","75 g","62,5 g","60 g","1/2 cuil. à moka","1","1/2 pincée"],steps:["Battre le beurre pommade avec le sucre jusqu'à ce que le mélange blanchisse.","Ajouter le sel et les œufs, bien mélanger.","Incorporer petit à petit la farine tamisée.","Ajouter le bicarbonate et les pépites de chocolat, mélanger jusqu'à obtenir une pâte homogène.","Former des petits tas de pâte sur une plaque recouverte de papier cuisson.","Enfourner 15 minutes à 180°C puis laisser refroidir à température ambiante."],diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
{n:"Clafoutis diététique à la rhubarbe et à l'édulcorant",cat:"dessert",tags:["perte_de_poids","equilibre"],kcal:233,p:10,c:29,f:9,prep:40,ing:["Rhubarbe","Farine","Édulcorant","Levure chimique","Oeufs","Lait écrémé","Beurre"],qty:["200 g","50 g","20 g","1/4 sachet","1 1/2","10 cl","10 g"],steps:["Préchauffer le four à 210°C.","Mélanger l'édulcorant, la farine et la levure dans un saladier.","Ajouter les œufs un à un, puis le beurre fondu et le lait, bien mélanger.","Incorporer les morceaux de rhubarbe.","Verser dans un plat à gratin beurré et fariné, enfourner 30 minutes."],diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
{n:"Gâteau Chocolat minceur",cat:"dessert",tags:["perte_de_poids","equilibre"],kcal:395,p:11,c:30,f:25,prep:35,ing:["Chocolat noir","Fromage blanc 0%","Maïzena","Oeufs","Édulcorant en poudre"],qty:["100 g","50 g","10 g","2","25 g"],steps:["Préchauffer le four à 200°C, faire fondre le chocolat au bain-marie et séparer les blancs des jaunes d'œufs.","Battre les jaunes avec l'édulcorant jusqu'à ce que le mélange blanchisse, ajouter la maïzena, le fromage blanc, le sel puis le chocolat fondu.","Monter les blancs en neige et les incorporer délicatement à la préparation.","Verser dans un moule rectangulaire beurré et enfourner environ 20 minutes."],diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Clafoutis rhubarbe minceur",cat:"dessert",tags:["perte_de_poids","equilibre"],kcal:414,p:11,c:65,f:12,prep:50,ing:["Rhubarbe","Sucre","Farine","Oeufs","Crème liquide allégée","Lait écrémé"],qty:["250 g","75 g","45 g","1 1/2","10 cl","10 cl"],steps:["Préchauffer le four à 180°C (th 6).","Plonger la rhubarbe coupée en tronçons 2 minutes dans l'eau bouillante puis l'égoutter en pressant.","Mélanger les œufs avec le sucre, ajouter la farine, la crème et le lait jusqu'à obtenir une préparation homogène.","Verser la rhubarbe dans un moule à gratin beurré, recouvrir de la préparation et enfourner 40 minutes."],diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
{n:"Tarte au citron healthy (IG bas)",cat:"dessert",tags:["perte_de_poids","equilibre"],kcal:695,p:14,c:55,f:49,prep:60,ing:["Farine d'épeautre","Farine d'orge mondé","Farine d'amande","Oeufs","Beurre","Huile de coco","Sucre muscovado","Citrons jaunes","Sirop d'agave","Stévia","Feuille de gélatine"],qty:["45 g","45 g","20 g","2","55 g","30 g","10 g","2","25 g","7,5 g","1"],steps:["Mélanger les farines avec le sucre muscovado et le sel, ajouter le beurre en morceaux et sabler du bout des doigts.","Ajouter un œuf et pétrir jusqu'à obtenir une pâte homogène, former une boule et réfrigérer 1 heure.","Étaler la pâte, foncer un moule beurré et fariné, égaliser les bords et réfrigérer 30 minutes.","Cuire à blanc 14 minutes à 180°C avec du papier cuisson et des légumes secs, puis laisser refroidir.","Presser le jus des citrons et faire ramollir la gélatine dans l'eau froide.","Mélanger les œufs restants avec le sirop d'agave et la stévia, chauffer en remuant jusqu'à épaississement.","Ajouter la gélatine égouttée, laisser refroidir puis verser la crème de citron sur le fond de tarte.","Réfrigérer 3 heures avant de servir."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:false}},
{n:"Cookies minceur",cat:"dessert",tags:["perte_de_poids","equilibre"],kcal:532,p:10,c:48,f:34,prep:85,ing:["Oeuf","Beurre","Stevia","Farine","Flocons d'avoine"],qty:["½","60 g","35 g","75 g","50 g"],steps:["Mélanger la stevia avec le beurre mou, puis ajouter l'oeuf et bien mélanger.","Incorporer la farine, la levure, le sel et les flocons d'avoine ; travailler la pâte à la main puis former un boudin d'environ 7 cm de diamètre et réserver au réfrigérateur 1 heure.","Préchauffer le four à 180°C (th.6), sortir la pâte et la couper en tranches d'environ 1 cm d'épaisseur.","Répartir les tranches sur une plaque recouverte de papier sulfurisé et enfourner 10 minutes."],diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
{n:"Clafoutis minceur à l'ananas et au fromage blanc",cat:"dessert",tags:["perte_de_poids","equilibre"],kcal:174,p:11,c:25,f:4,prep:50,ing:["Fromage blanc 0%","Ananas","Farine","Édulcorant","Oeufs"],qty:["125 g","¼","10 g","15 g","1 ½"],steps:["Préchauffer le four à 180°C (th.6).","Dans un saladier, mélanger le fromage blanc, les jaunes d'oeufs, l'édulcorant et la farine.","Monter les blancs en neige et les incorporer délicatement à la préparation. Éplucher et couper l'ananas en dés, puis l'ajouter au mélange.","Répartir dans des moules individuels et enfourner 35 minutes. Déguster froid ou tiède."],diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
{n:"Brownie healthy",cat:"dessert",tags:["perte_de_poids","equilibre"],kcal:614,p:16,c:61,f:34,prep:40,ing:["Chocolat noir","Cacao en poudre non sucré","Oeufs","Fromage blanc","Farine","Sucre rapadura","Noix concassées"],qty:["115 g","15 g","1 ½","55 g","37 ½ g","37 ½ g","quelques"],steps:["Préchauffer le four à 180°C.","Faire fondre le chocolat au bain-marie.","Séparer les jaunes des blancs d'oeufs et monter les blancs en neige avec une pincée de sel.","Blanchir les jaunes avec le sucre rapadura, puis mélanger au fromage blanc.","Ajouter la farine, la levure et la vanille liquide, puis le chocolat fondu.","Incorporer délicatement les blancs en neige à la maryse, puis ajouter les noix concassées.","Verser dans un moule en silicone et enfourner 25 minutes."],diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:false}},
{n:"Cookies choco-noisettes healthy",cat:"dessert",tags:["perte_de_poids","equilibre"],kcal:447,p:7,c:35,f:30,prep:23,ing:["Farine semi complète","Maïzena","Huile de coco","Chocolat à pâtisser","Sucre complet","Oeuf","Noisette","Pépites de chocolat"],qty:["20 g","10 g","15 g","60 g","12 ½ g","½","20 g","20 g"],steps:["Préchauffer le four à 180°C.","Faire fondre le chocolat avec l'huile de coco et réserver.","Dans un saladier, mélanger la farine, la maïzena et le sucre, puis ajouter l'oeuf et fouetter.","Ajouter le mélange chocolat-coco, puis les noisettes et les pépites de chocolat ; mélanger jusqu'à obtenir une pâte homogène.","Former 12 boules et aplatir légèrement avec la paume de la main.","Enfourner 8 minutes."],diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:true,sans_gluten:false,sans_fruits_a_coque:false}},
{n:"Mousse liégeoise healthy",cat:"dessert",tags:["perte_de_poids","equilibre"],kcal:350,p:8,c:21,f:23,prep:140,ing:["Blancs d'oeufs","Chocolat noir","Soja crème cuisine","Sucre vanillé","Grué de cacao caramélisé"],qty:["2","100 g","5 cl","½ sachet","5 g"],steps:["Monter la crème de soja en chantilly avec le sucre vanillé et réserver au frais.","Faire fondre le chocolat au bain-marie et laisser tiédir.","Monter les blancs d'oeufs en neige avec une pincée de sel.","Mélanger délicatement le chocolat fondu avec les blancs en neige à la spatule, puis verser dans de petits pots.","Dresser la chantilly sur la mousse au chocolat à l'aide d'une poche à douille et réserver au frais 2 heures.","Avant de servir, parsemer de grué de cacao caramélisé."],diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
];
